insert into public.content_assets(id,kind,storage_path,sha256,byte_size,mime_type) values('9ae52d1e-a521-560d-ae81-f295f98ab7ad','cover','covers/97e5be0a68f175eeab88d7cc12f244d09bdd68db830b8e3a8c46672b386a09c2.png','97e5be0a68f175eeab88d7cc12f244d09bdd68db830b8e3a8c46672b386a09c2',2359321,'image/png') on conflict do nothing;
insert into public.stories(id) values('quiet-morning') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','quiet-morning',1,'A Quiet Morning','English Tales','A1','Günlük yaşam','Küçük bir kasabada başlayan sıcak bir karşılaşma.','9ae52d1e-a521-560d-ae81-f295f98ab7ad');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-1',1,'It was a quiet morning in a small town.','Küçük bir kasabada sessiz bir sabahtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-2',2,'Mia walked to the bakery before school.','Mia okuldan önce fırına yürüdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-3',3,'The smell of fresh bread filled the street.','Taze ekmek kokusu sokağı doldurdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-4',4,'An old man stood outside and looked at the sky.','Yaşlı bir adam dışarıda durup gökyüzüne baktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-5',5,'Mia gave him a smile and said hello.','Mia ona gülümsedi ve merhaba dedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-6',6,'He told her that today was his birthday.','Adam ona bugün doğum günü olduğunu söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-7',7,'Mia bought two warm rolls and shared one with him.','Mia iki sıcak ekmek aldı ve birini onunla paylaştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-8',8,'They talked until the town became busy.','Kasaba hareketlenene kadar sohbet ettiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','qm-9',9,'A small act of kindness made the morning special.','Küçük bir iyilik sabahı özel kıldı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','quiet','quiet','sessiz','/ˈkwaɪət/','The street was quiet.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','bakery','bakery','fırın','/ˈbeɪkəri/','The bakery opened early.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('75d7940d-c902-5901-a9f1-7a59ec9eda21','smile','smile','gülümsemek','/smaɪl/','She gave him a warm smile.');
