insert into public.stories(id) values('paper-boat') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','paper-boat',1,'The Paper Boat','English Tales','A2','Macera','Bir kâğıt teknenin nehir üzerindeki yolculuğu.','ea7d35c6-d561-5385-a2a4-e3ed42be4a31');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-1',1,'Leo made a little boat from a blue piece of paper.','Leo mavi bir kâğıttan küçük bir tekne yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-2',2,'He carried it to the river near the old bridge.','Onu eski köprünün yakınındaki nehre götürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-3',3,'A gentle wind pushed the boat across the water.','Hafif bir rüzgâr tekneyi suyun üzerinde itti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-4',4,'Leo ran along the path to follow it.','Leo onu takip etmek için patika boyunca koştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-5',5,'The boat passed a family of ducks.','Tekne bir ördek ailesinin yanından geçti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-6',6,'Then it stopped beside a stone at the riverbank.','Sonra nehir kıyısındaki bir taşın yanında durdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-7',7,'A girl picked it up and wrote a message inside.','Bir kız onu aldı ve içine bir mesaj yazdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-8',8,'The message said, Every journey starts somewhere.','Mesajda, Her yolculuk bir yerden başlar, yazıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','pb-9',9,'Leo smiled and let the boat continue its journey.','Leo gülümsedi ve teknenin yolculuğuna devam etmesine izin verdi.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','boat','boat','tekne','/boʊt/','A little boat floated away.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','river','river','nehir','/ˈrɪvər/','The river moved slowly.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','bridge','bridge','köprü','/brɪdʒ/','They crossed the bridge.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','wind','wind','rüzgâr','/wɪnd/','The wind carried the boat.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','path','path','patika','/pæθ/','A narrow path led uphill.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('e073d1e6-8a97-50ea-a98a-71e52423fb74','journey','journey','yolculuk','/ˈdʒɜːrni/','Every journey starts somewhere.');
