insert into public.stories(id) values('lost-map') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('f218befa-b546-592c-a0e7-105bb860a126','lost-map',1,'The Lost Map','English Tales','B1','Gizem','Ormanda bulunan eski bir haritanın sırrı.','f11f9a44-c5f4-5197-aa54-acd65d67a14b');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-1',1,'Nora found an old map inside her grandfather''s desk.','Nora dedesinin masasının içinde eski bir harita buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-2',2,'A red line crossed a forest and ended at a lake.','Kırmızı bir çizgi ormanı geçip bir gölde bitiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-3',3,'She asked her friend Sam to explore the path with her.','Arkadaşı Sam''den patikayı birlikte keşfetmesini istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-4',4,'The forest was quiet except for birds in the trees.','Orman, ağaçlardaki kuşlar dışında sessizdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-5',5,'Near the lake, they discovered a wooden box.','Gölün yakınında ahşap bir kutu keşfettiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-6',6,'Inside was a photograph of their families many years ago.','İçinde ailelerinin yıllar önce çekilmiş bir fotoğrafı vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-7',7,'The map was not a guide to treasure.','Harita bir hazine rehberi değildi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-8',8,'It was a reminder of a friendship that had lasted for years.','Yıllardır süren bir dostluğun hatırlatıcısıydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('f218befa-b546-592c-a0e7-105bb860a126','lm-9',9,'Nora and Sam promised to return the next summer.','Nora ve Sam sonraki yaz geri dönmeye söz verdiler.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('f218befa-b546-592c-a0e7-105bb860a126','map','map','harita','/mæp/','The old map showed a path.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('f218befa-b546-592c-a0e7-105bb860a126','forest','forest','orman','/ˈfɔːrɪst/','The forest was full of birds.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('f218befa-b546-592c-a0e7-105bb860a126','path','path','patika','/pæθ/','A narrow path led uphill.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('f218befa-b546-592c-a0e7-105bb860a126','quiet','quiet','sessiz','/ˈkwaɪət/','The street was quiet.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('f218befa-b546-592c-a0e7-105bb860a126','return','return','dönmek','/rɪˈtɜːrn/','They promised to return.');
