insert into public.stories(id) values('attic-letter') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter',1,'The Attic Letter','English Tales','B1','Gizem','Tavan arasında bulunan eski bir mektup, ailede yıllardır anlatılmayan bir hikâyeyi ortaya çıkarıyor.','a89cf56f-deed-55ba-a361-91f539a73389');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-1',1,'While helping her grandmother clear the attic, Nora found a small wooden chest beneath a pile of blankets.','Nora, büyükannesinin tavan arasını toplamasına yardım ederken bir battaniye yığınının altında küçük bir ahşap sandık buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-2',2,'Inside it lay a photograph, a blue ribbon, and an envelope with no name on the front.','İçinde bir fotoğraf, mavi bir kurdele ve ön yüzünde isim yazmayan bir zarf vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-3',3,'The envelope was open, so Nora carefully unfolded the letter inside.','Zarf açıktı; Nora içindeki mektubu dikkatle açtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-4',4,'It described a promise to meet beside the old garden gate on the first day of spring.','Mektupta, baharın ilk günü eski bahçe kapısının yanında buluşmak için verilmiş bir söz anlatılıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-5',5,'There was no signature, only a drawing of a tiny bird in the corner.','İmza yoktu, yalnızca köşede küçük bir kuş çizimi vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-6',6,'Nora showed the letter to her grandmother, who became quiet when she saw the drawing.','Nora mektubu büyükannesine gösterdi; büyükannesi çizimi görünce sessizleşti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-7',7,'After a moment, she explained that her childhood friend used to sign every message that way.','Bir süre sonra çocukluk arkadaşının her mesajı bu şekilde imzaladığını açıkladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-8',8,'They had planned to create a garden together, but her friend had moved away before spring arrived.','Birlikte bir bahçe yapmayı planlamışlardı ama arkadaşı bahar gelmeden taşınmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-9',9,'Although they had kept in touch for years, the garden had remained only a memory.','Yıllarca iletişimde kalmalarına rağmen bahçe yalnızca bir anı olarak kalmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-10',10,'Nora asked whether the old gate still existed.','Nora eski bahçe kapısının hâlâ durup durmadığını sordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-11',11,'Her grandmother led her outside, where climbing plants almost covered a narrow wooden gate.','Büyükannesi onu dışarı çıkardı; dar ahşap kapı neredeyse tamamen sarmaşıklarla kaplıydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-12',12,'Beyond it was a patch of empty ground that received sunlight for most of the day.','Kapının ardında günün büyük bölümünde güneş alan boş bir toprak parçası vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-13',13,'Nora suggested planting a few flowers there before sending a photograph to the old friend.','Nora eski arkadaşa bir fotoğraf göndermeden önce oraya birkaç çiçek dikmeyi önerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-14',14,'Over the following week, they cleared the ground and chose seeds at the local shop.','Sonraki hafta boyunca toprağı temizlediler ve mahalledeki dükkândan tohum seçtiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-15',15,'Her grandmother wrote a new letter and placed the original blue ribbon around it.','Büyükannesi yeni bir mektup yazdı ve eski mavi kurdeleyi etrafına bağladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-16',16,'A reply arrived a few days later, ending with the familiar drawing of a bird.','Birkaç gün sonra bir cevap geldi; mektup tanıdık kuş çizimiyle bitiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-17',17,'Her friend promised to visit when the first flowers opened.','Arkadaşı ilk çiçekler açtığında ziyarete geleceğine söz verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-18',18,'Nora realized that the chest had held something more valuable than a secret: a chance to begin again.','Nora sandığın bir sırdan daha değerli bir şey sakladığını fark etti: yeniden başlamak için bir fırsat.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','attic','attic','tavan arası','/ˈætɪk/','Nora helped clear the attic.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','chest','chest','sandık','/tʃest/','She found a wooden chest.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','envelope','envelope','zarf','/ˈenvəloʊp/','The envelope was open.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','promise','promise','söz','/ˈprɑːmɪs/','The letter described a promise.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','gate','gate','bahçe kapısı','/ɡeɪt/','They met beside the gate.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','quiet','quiet','sessiz','/ˈkwaɪət/','The street was quiet.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','memory','memory','anı','/ˈmeməri/','The garden was only a memory.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','seeds','seeds','tohumlar','/siːdz/','They chose seeds at the shop.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('de98395d-f930-5840-a3da-ce46a9e06404','valuable','valuable','değerli','/ˈvæljuəbəl/','The letter was valuable to her.');
insert into public.sentence_words(revision_id,sentence_id,word_id) values('de98395d-f930-5840-a3da-ce46a9e06404','attic-letter-1','attic');
