insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','classic-tortoise-hare',1,'The Tortoise and the Hare','Aesop','A1','Macera','Tavşan ve Kaplumbağa. Hızlı bir tavşan ile kararlı bir kaplumbağanın yarışı. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','77e5dc84-6237-5f91-a0be-adf590b918a0');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-01',1,'A hare sees a tortoise on the road.','Bir tavşan yolda bir kaplumbağa görür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-02',2,'The hare laughs at the tortoise.','Tavşan kaplumbağaya güler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-03',3,'"You are so slow!" he says.','"Çok yavaşsın!" der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-04',4,'"I can win a race," says the tortoise.','"Bir yarışı kazanabilirim," der kaplumbağa.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-05',5,'The hare laughs again, but he agrees.','Tavşan yine güler ama kabul eder.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-06',6,'A fox shows them the finish line.','Bir tilki onlara bitiş çizgisini gösterir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-07',7,'The race starts, and the hare runs fast.','Yarış başlar ve tavşan hızla koşar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-08',8,'The tortoise walks slowly along the path.','Kaplumbağa patikada yavaşça yürür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-09',9,'The hare is far ahead.','Tavşan çok öndedir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-10',10,'"I have time for a rest," he thinks.','"Dinlenmek için zamanım var," diye düşünür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-11',11,'He lies down and falls asleep.','Uzanır ve uykuya dalar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-12',12,'The tortoise does not stop.','Kaplumbağa durmaz.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-13',13,'Step by step, she reaches the finish line.','Adım adım bitiş çizgisine ulaşır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-14',14,'The hare wakes up and runs.','Tavşan uyanır ve koşar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-15',15,'But the tortoise is already there.','Ama kaplumbağa çoktan oradadır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','cl-tortoise-hare-16',16,'Slow and steady work wins the race.','Yavaş ve kararlı bir çaba yarışı kazandırır.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','hare','hare','yaban tavşanı','/heə(r)/','The hare runs fast.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','tortoise','tortoise','kaplumbağa','/ˈtɔːtəs/','The tortoise keeps walking.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','road','road','yol','/roʊd/','The road goes to the village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','laughs','laughs','güler','/læfs/','She laughs at the funny story.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','slow','slow','yavaş','/sloʊ/','The old bus is very slow.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','race','race','yarış','/reɪs/','The race starts here.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','fox','fox','tilki','/fɒks/','The fox sees some grapes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','finish','finish','bitiş','/ˈfɪnɪʃ/','She reaches the finish line.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','slowly','slowly','yavaşça','/ˈsloʊli/','They walk slowly.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','path','path','patika','/pæθ/','A narrow path led uphill.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','ahead','ahead','önde, ileride','/əˈhed/','The school is just ahead.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','rest','rest','dinlenme','/rest/','We need a short rest after the walk.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','step','step','adım','/step/','Take one step at a time.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','steady','steady','kararlı','/ˈstedi/','Slow and steady work brings results.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4ee49bb8-ef6e-5556-a487-3a4bab5f2225','wins','wins','kazanır','/wɪnz/','Our team wins the game.');
