insert into public.content_assets(id,kind,storage_path,sha256,byte_size,mime_type) values('040dd483-0307-5abf-a419-7d8bbbbf6ebb','cover','covers/3e4243044fbc786aca0f2775679e25b4148a0d569c5f0d9e1bf84d44f4868a17.png','3e4243044fbc786aca0f2775679e25b4148a0d569c5f0d9e1bf84d44f4868a17',110869,'image/png') on conflict do nothing;
insert into public.stories(id) values('classic-red-riding-hood') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','classic-red-riding-hood',1,'Little Red Riding Hood','Jacob and Wilhelm Grimm','A2','Macera','Kırmızı Başlıklı Kız. Büyükannesine giderken yoldan ayrılan bir kızın ormandaki macerası. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','040dd483-0307-5abf-a419-7d8bbbbf6ebb');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-01',1,'Everyone called the girl Little Red Riding Hood because of her red cap.','Kırmızı başlığı yüzünden herkes kıza Kırmızı Başlıklı Kız derdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-02',2,'One day, her mother asked her to visit her sick grandmother.','Bir gün annesi, hasta büyükannesini ziyaret etmesini istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-03',3,'She gave the girl cake and a bottle of wine.','Kıza kek ve bir şişe şarap verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-04',4,'"Stay on the path through the forest," her mother said.','"Ormandaki patikadan ayrılma," dedi annesi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-05',5,'The girl promised to be careful and set off.','Kız dikkatli olacağına söz verip yola çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-06',6,'On the way, a wolf asked where she was going.','Yolda bir kurt nereye gittiğini sordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-07',7,'She told him about the little house under the oak trees.','Ona meşe ağaçlarının altındaki küçük evi anlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-08',8,'The wolf suggested picking flowers for her grandmother.','Kurt, büyükannesi için çiçek toplamasını önerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-09',9,'While she left the path, he ran straight to the house.','Kız patikadan ayrılırken kurt doğruca eve koştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-10',10,'He pretended to be the girl, and the grandmother told him to come in.','Kızmış gibi davrandı ve büyükanne ona içeri girmesini söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-11',11,'The wolf swallowed her, put on her cap, and lay in her bed.','Kurt onu yuttu, başlığını taktı ve yatağına uzandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-12',12,'When the girl arrived, the door was open.','Kız geldiğinde kapı açıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-13',13,'Her grandmother looked very strange under the blankets.','Büyükannesi battaniyelerin altında çok tuhaf görünüyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-14',14,'"What big ears you have!" the girl said.','"Ne büyük kulakların var!" dedi kız.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-15',15,'"They help me hear you better," answered the wolf.','"Seni daha iyi duymamı sağlıyorlar," diye cevap verdi kurt.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-16',16,'The girl asked about his big eyes and large hands, too.','Kız onun büyük gözlerini ve kocaman ellerini de sordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-17',17,'Then she noticed his enormous mouth.','Sonra onun kocaman ağzını fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-18',18,'"It helps me eat you!" he cried, and swallowed her.','"Seni yememi sağlıyor!" diye bağırdı ve onu yuttu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-19',19,'Soon the wolf fell asleep and began to snore.','Çok geçmeden kurt uykuya daldı ve horlamaya başladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-20',20,'A hunter passing the house heard the noise.','Evin önünden geçen bir avcı gürültüyü duydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-21',21,'He found the wolf and thought the grandmother might still be alive.','Kurdu buldu ve büyükannenin hâlâ hayatta olabileceğini düşündü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-22',22,'He carefully cut open the sleeping wolf''s belly with scissors.','Uyuyan kurdun karnını makasla dikkatlice açtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-23',23,'The girl and her grandmother climbed out alive.','Kız ile büyükannesi sağ olarak dışarı çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-24',24,'They filled the wolf''s belly with stones, and he died when he tried to run.','Kurdun karnını taşlarla doldurdular ve kurt koşmaya çalıştığında öldü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-25',25,'The grandmother enjoyed her food, and the girl remembered her mother''s warning.','Büyükanne yemeğini afiyetle yedi ve kız annesinin uyarısını hatırladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-26',26,'On a later visit, another wolf tried to stop the girl.','Daha sonraki bir ziyaretinde başka bir kurt kızı durdurmaya çalıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-27',27,'This time, she went straight to her grandmother and told her everything.','Bu kez doğruca büyükannesine gidip ona her şeyi anlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-28',28,'They kept the door shut and filled a trough with water that smelled of sausages.','Kapıyı kapalı tuttular ve bir yalağı sosis kokulu suyla doldurdular.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-29',29,'The wolf leaned down from the roof, fell into the water, and drowned.','Kurt çatıdan aşağı eğildi, suya düştü ve boğuldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-30',30,'The girl went home safely after listening to good advice.','Kız iyi öğütleri dinleyerek güvenle evine döndü.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cap','cap','başlık','/kæp/','The girl wears a red cap.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','path','path','patika','/pæθ/','A narrow path led uphill.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','forest','forest','orman','/ˈfɔːrɪst/','The forest was full of birds.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','wolf','wolf','kurt','/wʊlf/','The wolf runs to the house.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','oak','oak','meşe','/əʊk/','The house stands under oak trees.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','mouth','mouth','ağız','/maʊθ/','A dog carries a piece of meat in his mouth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','hunter','hunter','avcı','/ˈhʌntə(r)/','A hunter hears the noise.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','belly','belly','karın','/ˈbeli/','The wolf has a full belly.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','scissors','scissors','makas','/ˈsɪzəz/','He carefully uses the scissors.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','food','food','yiyecek','/fuːd/','He offers simple food from the fields.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','warning','warning','uyarı','/ˈwɔːnɪŋ/','She remembers her mother''s warning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','safely','safely','güvenli bir şekilde','/ˈseɪfli/','He put the ticket safely in his pocket.');
insert into public.sentence_words(revision_id,sentence_id,word_id) values('d2c319e7-2f1a-5fd8-aeaf-76ad28675072','cl-red-riding-hood-01','cap');
