insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','classic-cinderella',1,'Cinderella','Jacob and Wilhelm Grimm','A2','Macera','Külkedisi. Grimm anlatısındaki fındık ağacı, yardımcı kuşlar ve altın ayakkabı. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','efa27c15-cf1c-5bd9-a6c9-b9b8f503924e');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-01',1,'After her mother died, a young girl lived with her father and his new family.','Annesi öldükten sonra genç bir kız, babası ve onun yeni ailesiyle yaşadı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-02',2,'Her stepmother and stepsisters made her do all the hard work.','Üvey annesi ile üvey kız kardeşleri bütün zor işleri ona yaptırıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-03',3,'She slept beside the fire, so they called her Cinderella.','Ocağın yanında uyuduğu için ona Külkedisi diyorlardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-04',4,'When her father went away, she asked him for a branch.','Babası yolculuğa çıktığında ondan bir dal istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-05',5,'She planted the hazel branch on her mother''s grave.','Fındık dalını annesinin mezarına dikti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-06',6,'It grew into a tree, and a white bird came to it.','Dal bir ağaca dönüştü ve ağaca beyaz bir kuş geldi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-07',7,'The bird brought her things she wished for.','Kuş ona dilediği şeyleri getiriyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-08',8,'One day, the king invited young women to a three-day festival.','Bir gün kral genç kadınları üç günlük bir şenliğe davet etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-09',9,'His son hoped to find a bride there.','Oğlu orada evleneceği kişiyi bulmayı umuyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-10',10,'Cinderella wanted to go, but her stepmother gave her more work.','Külkedisi gitmek istiyordu ama üvey annesi ona daha fazla iş verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-11',11,'Birds helped her pick lentils out of the ashes.','Kuşlar küllerin arasından mercimekleri ayıklamasına yardım etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-12',12,'Even then, her stepmother would not let her go.','Buna rağmen üvey annesi gitmesine izin vermedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-13',13,'Cinderella went to the hazel tree and asked for help.','Külkedisi fındık ağacına gidip yardım istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-14',14,'The bird gave her a beautiful dress and fine slippers.','Kuş ona güzel bir elbise ve zarif ayakkabılar verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-15',15,'At the palace, the prince danced only with her.','Sarayda prens yalnızca onunla dans etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-16',16,'She escaped before he could find out where she lived.','Prens nerede yaşadığını öğrenemeden oradan kaçtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-17',17,'She returned on the next two days in even finer dresses.','Sonraki iki gün daha da güzel elbiselerle geri döndü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-18',18,'On the third evening, the prince put sticky pitch on the stairs.','Üçüncü akşam prens merdivenlere yapışkan zift sürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-19',19,'As she hurried away, one golden slipper stuck there.','Kız aceleyle uzaklaşırken altın ayakkabılarından biri oraya yapıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-20',20,'The prince said he would marry the woman whose foot fitted it.','Prens, ayakkabı ayağına uyan kadınla evleneceğini söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-21',21,'Each stepsister injured her foot to force it into the slipper.','Üvey kız kardeşlerin her biri ayağını ayakkabıya zorla sokmak için yaraladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-22',22,'But the birds warned the prince, and he discovered the blood.','Ama kuşlar prensi uyardı ve prens kanı fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-23',23,'At last, he insisted on seeing Cinderella.','Sonunda Külkedisi''ni görmekte ısrar etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-24',24,'She washed her face and tried on the golden slipper.','Kız yüzünü yıkadı ve altın ayakkabıyı denedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-25',25,'It fitted perfectly, and the prince recognized his dancing partner.','Ayakkabı tam oldu ve prens dans ettiği kızı tanıdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-26',26,'He took her away, with two white birds sitting on her shoulders.','Omuzlarında iki beyaz kuş oturan kızı yanına alıp götürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-27',27,'At the wedding, the stepsisters tried to share Cinderella''s good fortune.','Düğünde üvey kız kardeşleri Külkedisi''nin mutluluğundan pay almaya çalıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','cl-cinderella-28',28,'The birds punished their cruelty by taking away their sight.','Kuşlar onların görme yetisini alarak zalimliklerini cezalandırdı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','father','father','baba','/ˈfɑːðə(r)/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','hazel','hazel','fındık','/ˈheɪzl/','A hazel tree grows there.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','grave','grave','mezar','/ɡreɪv/','She visits her mother''s grave.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','festival','festival','şenlik','/ˈfestɪvl/','The festival lasts three days.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','bride','bride','gelin','/braɪd/','The prince hopes to find a bride.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','lentils','lentils','mercimekler','/ˈlentlz/','The birds pick up the lentils.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','ashes','ashes','küller','/ˈæʃɪz/','She sits beside the ashes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','dress','dress','elbise','/dres/','"Then I can sell the chickens and buy a fine dress."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','pitch','pitch','zift','/pɪtʃ/','Sticky pitch covers the stairs.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','golden','golden','altın; altından','/ˈɡəʊldən/','Every day, she lays a golden egg.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','slipper','slipper','ayakkabı','/ˈslɪpə(r)/','The golden slipper fits her.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','force','force','güç; zor kullanma','/fɔːs/','The Sun wins without using force.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','share','share','paylaşmak','/ʃer/','They share the cake.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fea96f9e-51a6-5fe8-a06c-b47c3b1f3f15','fortune','fortune','talih; servet','/ˈfɔːtʃuːn/','His greed has taken away his good fortune.');
