insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','classic-bremen-musicians',1,'The Bremen Town Musicians','Jacob and Wilhelm Grimm','A2','Macera','Bremen Mızıkacıları. Yeni bir hayat arayan dört yaşlı hayvanın dayanışması. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','9aa96897-87ed-5d19-af6e-f2b0dd83dc05');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-01',1,'An old donkey could no longer carry heavy sacks for his master.','Yaşlı bir eşek artık sahibi için ağır çuvallar taşıyamıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-02',2,'Afraid of what would happen, he ran away toward Bremen.','Başına geleceklerden korkarak Bremen''e doğru kaçtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-03',3,'He wanted to earn his living as a musician.','Müzisyen olarak geçimini sağlamak istiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-04',4,'On the road, he met an old dog who had escaped from his master.','Yolda sahibinden kaçmış yaşlı bir köpekle karşılaştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-05',5,'"Come with me, and we can make music together," said the donkey.','"Benimle gel, birlikte müzik yapabiliriz," dedi eşek.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-06',6,'Next, they found a cat whose owner no longer wanted her.','Sonra sahibinin artık istemediği bir kedi buldular.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-07',7,'She joined them, and soon they met a rooster on a gate.','Kedi onlara katıldı ve çok geçmeden bir kapının üzerinde bir horozla karşılaştılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-08',8,'The rooster was going to become soup the next day.','Horoz ertesi gün çorba yapılacaktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-09',9,'He agreed that being a musician was a much better plan.','Müzisyen olmanın çok daha iyi bir plan olduğunu kabul etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-10',10,'By evening, the four animals were still far from Bremen.','Akşam olduğunda dört hayvan hâlâ Bremen''den uzaktaydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-11',11,'They rested in a forest, where the rooster noticed a light.','Bir ormanda dinlendiler ve horoz orada bir ışık fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-12',12,'Following it, they found a house full of robbers.','Işığı takip ederek içi haydutlarla dolu bir ev buldular.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-13',13,'Through the window, the donkey saw a table covered with food.','Eşek pencereden üzeri yiyeceklerle dolu bir masa gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-14',14,'The hungry friends made a plan to frighten the robbers away.','Aç dostlar haydutları korkutup kaçırmak için bir plan yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-15',15,'The dog climbed onto the donkey, and the cat climbed onto the dog.','Köpek eşeğin, kedi de köpeğin üzerine çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-16',16,'The rooster stood on top of the cat.','Horoz kedinin tepesinde durdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-17',17,'Together they made a terrible noise and burst through the window.','Birlikte korkunç bir gürültü çıkarıp pencereden içeri daldılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-18',18,'Thinking a ghost had arrived, the robbers ran into the forest.','Bir hayaletin geldiğini sanan haydutlar ormana kaçtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-19',19,'The animals ate their supper and found places to sleep.','Hayvanlar akşam yemeklerini yedi ve uyuyacak yerler buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-20',20,'After midnight, one robber returned to look inside.','Gece yarısından sonra bir haydut içeri bakmak için döndü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-21',21,'The cat scratched him, the dog bit him, and the donkey kicked him.','Kedi onu tırmaladı, köpek ısırdı ve eşek tekmeledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-22',22,'Then the rooster called loudly from the roof.','Sonra horoz çatıdan yüksek sesle öttü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-23',23,'The frightened robber described a witch, an armed man, a monster, and a judge.','Korkmuş haydut bir cadıdan, silahlı bir adamdan, bir canavardan ve bir yargıçtan söz etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-24',24,'None of the robbers dared to go back.','Haydutların hiçbiri geri dönmeye cesaret edemedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','cl-bremen-musicians-25',25,'The four friends liked their new home so much that they never left for Bremen.','Dört dost yeni evlerini o kadar sevdi ki Bremen''e gitmek üzere bir daha yola çıkmadılar.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','donkey','donkey','eşek','/ˈdɒŋki/','The donkey carries sacks.');
