insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','musician','musician','müzisyen','/mjuˈzɪʃn/','The donkey wants to be a musician.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','road','road','yol','/roʊd/','The road goes to the village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','dog','dog','köpek','/dɒɡ/','A dog carries a piece of meat in his mouth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','rooster','rooster','horoz','/ˈruːstə(r)/','The rooster sings loudly.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','gate','gate','bahçe kapısı','/ɡeɪt/','They met beside the gate.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','much','much','çok','/mʌtʃ/','Thank you very much.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','animals','animals','hayvanlar','/ˈænɪmlz/','He walks around and frightens the animals.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','forest','forest','orman','/ˈfɔːrɪst/','The forest was full of birds.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','robbers','robbers','haydutlar','/ˈrɒbəz/','The robbers leave the house.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','window','window','pencere','/ˈwɪndoʊ/','Anna looks out of her window.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','food','food','yiyecek','/fuːd/','He offers simple food from the fields.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','hungry','hungry','aç','/ˈhʌŋɡri/','I am hungry after school.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','supper','supper','akşam yemeği','/ˈsʌpə(r)/','The animals eat their supper.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','scratched','scratched','tırmaladı','/skrætʃt/','The cat scratched the robber.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','frightened','frightened','korkmuş','/ˈfraɪtnd/','The frightened cat hides under the bed.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','witch','witch','cadı','/wɪtʃ/','The old woman is a witch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('840fcdb2-5473-5bb2-a9cb-12b98959298b','monster','monster','canavar','/ˈmɒnstə(r)/','The robber thinks he sees a monster.');
