insert into public.content_assets(id,kind,storage_path,sha256,byte_size,mime_type) values('4d1b9680-a9f2-5be7-a1d9-83bea90baa6d','cover','covers/a3d461c45ae03679605e330edcb2815f191ca12626161497bfaf28a9b371a6db.png','a3d461c45ae03679605e330edcb2815f191ca12626161497bfaf28a9b371a6db',456466,'image/png') on conflict do nothing;
insert into public.stories(id) values('classic-happy-prince') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','classic-happy-prince',1,'The Happy Prince','Oscar Wilde','B1','Günlük yaşam','Mutlu Prens. Bir heykel ile bir kırlangıcın, şehrin yoksullarına yardım etmek için yaptıkları fedakârlık. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Charles Robinson; koleksiyon kapağı, ayrı bir ilk baskı kapağı değildir.','4d1b9680-a9f2-5be7-a1d9-83bea90baa6d');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-01',1,'High above the city stood a statue covered in thin leaves of gold.','Şehrin yükseklerinde, ince altın yapraklarla kaplı bir heykel duruyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-02',2,'Its eyes were blue sapphires, and a red ruby shone on its sword.','Gözleri mavi safirlerdi ve kılıcında kırmızı bir yakut parlıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-03',3,'People admired the beautiful statue and called it the Happy Prince.','İnsanlar güzel heykele hayran oluyor ve ona Mutlu Prens diyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-04',4,'One evening, a swallow stopped at its feet on his way to Egypt.','Bir akşam, Mısır''a gitmekte olan bir kırlangıç heykelin ayaklarının dibinde konakladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-05',5,'Drops fell on the bird, although there were no clouds in the sky.','Gökyüzünde hiç bulut olmadığı hâlde kuşun üzerine damlalar düştü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-06',6,'When he looked up, he realized that the Prince was crying.','Yukarı baktığında Prens''in ağladığını fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-07',7,'While alive, the Prince had lived behind palace walls, far from other people''s troubles.','Prens hayattayken saray duvarlarının ardında, başkalarının dertlerinden uzakta yaşamıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-08',8,'Now he could see the suffering that his comfortable life had hidden from him.','Şimdi, rahat hayatının kendisinden gizlediği acıları görebiliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-09',9,'He asked the swallow to carry his ruby to a poor woman whose son was ill.','Kırlangıçtan yakutunu, oğlu hasta olan yoksul bir kadına götürmesini istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-10',10,'The bird wanted to leave for warmer lands, but agreed to stay one night.','Kuş daha sıcak ülkelere gitmek istiyordu ama bir gece kalmayı kabul etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-11',11,'He left the ruby beside the woman''s sewing things and cooled the boy with his wings.','Yakutu kadının dikiş eşyalarının yanına bıraktı ve kanatlarıyla çocuğu serinletti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-12',12,'When he returned, helping someone had made him feel strangely warm.','Geri döndüğünde birine yardım etmek, içini tuhaf bir sıcaklıkla doldurmuştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-13',13,'The following night, the Prince noticed a young writer who had no food or fire.','Ertesi gece Prens, yiyeceği ve yakacak ateşi olmayan genç bir yazar fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-14',14,'He asked the swallow to take one of his sapphire eyes to the writer.','Kırlangıçtan safir gözlerinden birini yazara götürmesini istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-15',15,'The bird was upset, but he carried out the Prince''s request.','Kuş üzülse de Prens''in isteğini yerine getirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-16',16,'Next, the Prince saw a girl whose matches had fallen into the wet street.','Sonra Prens, kibritleri ıslak sokağa düşmüş bir kız gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-17',17,'Without money, she was afraid to return to her father.','Para kazanamadığı için babasının yanına dönmekten korkuyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-18',18,'The Prince gave her his second sapphire, even though this left him blind.','Prens, kör kalmasına rağmen ikinci safirini de ona verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-19',19,'The swallow decided to stay and become his eyes.','Kırlangıç kalmaya ve onun gözleri olmaya karar verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-20',20,'Each day, he flew over the city and described the hungry families he saw.','Her gün şehrin üzerinde uçuyor ve gördüğü aç aileleri anlatıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-21',21,'The Prince told him to remove his gold leaves and give them to the poor.','Prens ondan altın yapraklarını çıkarıp yoksullara vermesini istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-22',22,'As the statue became dull and grey, children in the streets could finally buy bread.','Heykel donuklaşıp grileşirken sokaklardaki çocuklar sonunda ekmek alabiliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-23',23,'Winter arrived, but the swallow refused to abandon his friend.','Kış geldi ama kırlangıç dostunu terk etmeyi reddetti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-24',24,'At last, weakened by the cold, he said goodbye and died at the Prince''s feet.','Sonunda soğuktan güçsüz düşerek veda etti ve Prens''in ayaklarının dibinde öldü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-25',25,'At that moment, the statue''s lead heart broke in two.','O anda heykelin kurşun kalbi ikiye ayrıldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-26',26,'The next morning, the mayor saw only an ugly statue and ordered it taken down.','Ertesi sabah belediye başkanı yalnızca çirkin bir heykel gördü ve indirilmesini emretti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-27',27,'Workers melted the metal, but the broken heart would not melt.','İşçiler metali eritti ama kırık kalp erimedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-28',28,'They threw it away beside the dead bird.','Onu ölü kuşun yanına attılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-29',29,'God asked an angel to bring the two most precious things in the city.','Tanrı bir melekten şehrin en değerli iki şeyini getirmesini istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','cl-happy-prince-30',30,'The angel chose the broken heart and the swallow, and God welcomed them into Paradise.','Melek kırık kalbi ve kırlangıcı seçti; Tanrı da onları cennetine kabul etti.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','high','high','yüksek','/haɪ/','The bird sits on a high wall.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','statue','statue','heykel','/ˈstætʃuː/','The statue stands above the city.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','gold','gold','altın','/ɡəʊld/','He wants all the gold at once.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','sapphires','sapphires','safirler','/ˈsæfaɪəz/','The statue has sapphires for eyes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','ruby','ruby','yakut','/ˈruːbi/','A ruby shines on his sword.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','swallow','swallow','kırlangıç','/ˈswɒləʊ/','The swallow flies across the city.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','suffering','suffering','acı','/ˈsʌfərɪŋ/','The Prince sees the people''s suffering.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','boy','boy','erkek çocuk, oğlan','/bɔɪ/','The boy plays in the park.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','wings','wings','kanatlar','/wɪŋz/','Their long necks and powerful wings filled him with a feeling he did not understand.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','food','food','yiyecek','/fuːd/','He offers simple food from the fields.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','matches','matches','kibritler','/ˈmætʃɪz/','A little girl walked alone, trying to sell matches.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','money','money','para','/ˈmʌni/','She thinks about the money she can earn.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','return','return','dönmek','/rɪˈtɜːrn/','They promised to return.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','father','father','baba','/ˈfɑːðə(r)/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','second','second','ikinci','/ˈsekənd/','This is my second visit.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','blind','blind','kör','/blaɪnd/','Blind and unhappy, he wandered for years until he heard Rapunzel''s voice again.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','hungry','hungry','aç','/ˈhʌŋɡri/','I am hungry after school.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','winter','winter','kış','/ˈwɪntə(r)/','Winter is cold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('020a4ce1-c4d6-5be4-a923-3c9d3c4f071a','lead','lead','kurşun','/led/','The statue''s heart is made of lead.');
