insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('a7478442-58f3-5bee-a55d-a63d103a107d','classic-selfish-giant',1,'The Selfish Giant','Oscar Wilde','B1','Macera','Bencil Dev. Bahçesini çocuklara kapatan bir devin, paylaşmayı öğrenince değişen hayatı. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Charles Robinson; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','a3654ad9-3af0-5de4-acbd-c43402382b96');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-01',1,'Every afternoon, children played in a beautiful garden filled with peach trees.','Çocuklar her öğleden sonra şeftali ağaçlarıyla dolu güzel bir bahçede oynuyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-02',2,'The garden belonged to a giant who had been away for seven years.','Bahçe, yedi yıldır uzaklarda olan bir deve aitti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-03',3,'When he returned, he angrily ordered the children to leave.','Geri döndüğünde çocuklara öfkeyle gitmelerini emretti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-04',4,'He built a high wall because he wanted the garden entirely for himself.','Bahçeyi tamamen kendisine istediği için yüksek bir duvar ördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-05',5,'The children missed their playground and wandered along the dusty road outside.','Çocuklar oyun alanlarını özlüyor ve dışarıdaki tozlu yolda dolaşıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-06',6,'Spring brought flowers and birds to every other garden.','Bahar, diğer bütün bahçelere çiçekler ve kuşlar getirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-07',7,'Inside the giant''s walls, however, winter refused to end.','Ama devin duvarlarının içinde kış bitmek bilmiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-08',8,'Snow, frost, and the north wind made themselves at home.','Kar, don ve kuzey rüzgârı orayı evleri gibi benimsemişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-09',9,'Neither summer nor autumn brought the giant any fruit.','Ne yaz ne de sonbahar deve meyve getirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-10',10,'One morning, a bird''s song drew him to the window.','Bir sabah bir kuşun şarkısı onu pencereye çekti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-11',11,'Children had slipped through a hole in the wall and climbed into the trees.','Çocuklar duvardaki bir delikten geçip ağaçlara tırmanmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-12',12,'Wherever a child sat, blossoms appeared and birds began to sing.','Bir çocuğun oturduğu her yerde çiçekler açıyor ve kuşlar şakımaya başlıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-13',13,'Only one corner remained frozen, where a tiny boy could not reach a branch.','Yalnızca küçücük bir çocuğun dala ulaşamadığı bir köşe donmuş hâlde kalmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-14',14,'Seeing the boy''s tears, the giant understood how selfish he had been.','Çocuğun gözyaşlarını görünce dev ne kadar bencil davrandığını anladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-15',15,'He went outside, but the frightened children ran away and winter returned.','Dışarı çıktı ama korkmuş çocuklar kaçtı ve kış geri döndü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-16',16,'The little boy stayed because his tears prevented him from seeing the giant.','Küçük çocuk kaldı çünkü gözyaşları devi görmesine engel oluyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-17',17,'Gently, the giant lifted him into the tree.','Dev onu nazikçe kaldırıp ağaca yerleştirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-18',18,'Flowers immediately opened, and the boy hugged and kissed him.','Çiçekler hemen açıldı ve çocuk ona sarılıp onu öptü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-19',19,'When the other children saw this, they came back with the spring.','Diğer çocuklar bunu görünce baharla birlikte geri döndü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-20',20,'The giant knocked down the wall and gave them the garden to play in.','Dev duvarı yıktı ve oynamaları için bahçeyi onlara verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-21',21,'From then on, he welcomed the children every afternoon.','O günden sonra çocukları her öğleden sonra sevinçle karşıladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-22',22,'But the little boy who had changed his heart did not return.','Ama onun kalbini değiştiren küçük çocuk geri dönmedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-23',23,'The giant often asked about him, although nobody knew where he lived.','Kimse nerede yaşadığını bilmediği hâlde dev onu sık sık soruyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-24',24,'Years passed, and the giant grew too weak to join the children''s games.','Yıllar geçti ve dev çocukların oyunlarına katılamayacak kadar güçsüzleşti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-25',25,'He watched them from his chair, thinking they were more beautiful than any flowers.','Onları koltuğundan izliyor, bütün çiçeklerden daha güzel olduklarını düşünüyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-26',26,'One winter morning, he saw the little boy beneath a tree covered in white blossoms.','Bir kış sabahı küçük çocuğu beyaz çiçeklerle kaplı bir ağacın altında gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-27',27,'The giant ran to him and noticed marks on his hands and feet.','Dev ona koştu ve ellerindeki ve ayaklarındaki izleri fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-28',28,'Angry that someone had hurt the child, he asked who was responsible.','Birinin çocuğa zarar vermesine öfkelenerek bunu kimin yaptığını sordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-29',29,'The boy called the marks wounds of love, and the giant knelt before him.','Çocuk izlere sevginin yaraları dedi ve dev onun önünde diz çöktü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-30',30,'Because the giant had once shared his garden, the child now invited him to Paradise.','Dev bir zamanlar bahçesini paylaştığı için çocuk şimdi onu cennete davet ediyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a7478442-58f3-5bee-a55d-a63d103a107d','cl-selfish-giant-31',31,'That afternoon, the children found the giant dead beneath the tree, covered in white blossoms.','O öğleden sonra çocuklar devi ağacın altında ölmüş, beyaz çiçeklerle kaplanmış hâlde buldu.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','giant','giant','dev','/ˈdʒaɪənt/','The giant owns a garden.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','high','high','yüksek','/haɪ/','The bird sits on a high wall.');
