insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','road','road','yol','/roʊd/','The road goes to the village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','winter','winter','kış','/ˈwɪntə(r)/','Winter is cold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','frost','frost','don','/frɒst/','Frost covers the empty garden.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','north','north','kuzey','/nɔːθ/','The North Wind and the Sun argue.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','wind','wind','rüzgâr','/wɪnd/','The wind carried the boat.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','window','window','pencere','/ˈwɪndoʊ/','Anna looks out of her window.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','hole','hole','delik','/həʊl/','The mice run and hide in a hole.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','blossoms','blossoms','ağaç çiçekleri','/ˈblɒsəmz/','White blossoms cover the tree.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','boy','boy','erkek çocuk, oğlan','/bɔɪ/','The boy plays in the park.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','reach','reach','ulaşmak, uzanmak','/riːtʃ/','I cannot reach the top shelf.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','tears','tears','gözyaşları','/tɪəz/','Her tears fell into his eyes, and he could see once more.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','selfish','selfish','bencil','/ˈselfɪʃ/','The selfish giant builds a wall.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','frightened','frightened','korkmuş','/ˈfraɪtnd/','The frightened cat hides under the bed.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','return','return','dönmek','/rɪˈtɜːrn/','They promised to return.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','nobody','nobody','hiç kimse','/ˈnoʊbədi/','Nobody is at home today.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a7478442-58f3-5bee-a55d-a63d103a107d','knelt','knelt','diz çöktü','/nelt/','The giant knelt before the child.');
