insert into public.stories(id) values('classic-gift-magi') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('01bf33c9-242c-5939-a594-c24dabe7e8de','classic-gift-magi',1,'The Gift of the Magi','O. Henry','B1','Günlük yaşam','Noel Hediyesi. Birbirlerine hediye almak için en değerli eşyalarından vazgeçen Della ile Jim. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales.','8eff7469-3304-56e2-ac5f-6145e7eaf667');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-01',1,'On Christmas Eve, Della counted her savings for the third time.','Noel arifesinde Della birikimini üçüncü kez saydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-02',2,'She had only one dollar and eighty-seven cents to buy a present for Jim.','Jim''e bir hediye almak için yalnızca bir dolar seksen yedi senti vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-03',3,'Their small flat was cheap, but their expenses had still been greater than expected.','Küçük daireleri ucuzdu ama masrafları yine de beklediklerinden fazla olmuştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-04',4,'Jim''s wages had fallen, and saving even a few pennies had been difficult.','Jim''in ücreti düşmüştü ve birkaç sent biriktirmek bile zor olmuştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-05',5,'Della wanted to give her husband something worthy of her love.','Della kocasına sevgisine layık bir şey vermek istiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-06',6,'The couple owned two things they were especially proud of.','Çiftin özellikle gurur duyduğu iki şey vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-07',7,'One was Jim''s gold watch, inherited from his father and grandfather.','Bunlardan biri, Jim''in babasından ve büyükbabasından kalan altın saatiydi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-08',8,'The other was Della''s beautiful brown hair, which fell below her knees.','Diğeri, Della''nın dizlerinin aşağısına kadar uzanan güzel kahverengi saçlarıydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-09',9,'Looking in the mirror, Della suddenly knew how to buy her gift.','Aynaya bakan Della, hediyesini nasıl alacağını birden anladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-10',10,'She hurried to a woman who bought and sold hair.','Saç alıp satan bir kadına aceleyle gitti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-11',11,'The woman offered twenty dollars, and Della agreed to have her hair cut.','Kadın yirmi dolar teklif etti ve Della saçını kestirmeyi kabul etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-12',12,'For the next two hours, she searched the shops for the perfect present.','Sonraki iki saat boyunca dükkânlarda kusursuz hediyeyi aradı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-13',13,'Finally, she found a simple platinum chain for Jim''s watch.','Sonunda Jim''in saati için sade bir platin zincir buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-14',14,'It cost twenty-one dollars, leaving her just eighty-seven cents.','Zincir yirmi bir dolardı ve Della''nın elinde yalnızca seksen yedi sent kaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-15',15,'At home, she curled her short hair and worried about Jim''s reaction.','Evde kısa saçlarını kıvırdı ve Jim''in tepkisi için endişelendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-16',16,'When he opened the door, he stood still and stared at her.','Jim kapıyı açtığında olduğu yerde kalıp ona baktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-17',17,'Della explained that she had sold her hair because she wanted to give him a present.','Della ona bir hediye vermek istediği için saçını sattığını açıkladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-18',18,'She reminded him that her hair would grow again.','Saçının yeniden uzayacağını ona hatırlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-19',19,'Jim hugged her and said that no haircut could make him love her less.','Jim ona sarıldı ve hiçbir saç kesiminin sevgisini azaltamayacağını söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-20',20,'Then he handed her a package that explained his strange expression.','Sonra ona, yüzündeki tuhaf ifadeyi açıklayan bir paket verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-21',21,'Inside were the beautiful, expensive combs she had admired in a shop window.','İçinde, bir dükkânın vitrininde hayranlıkla baktığı güzel ve pahalı taraklar vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-22',22,'She held them close, although she no longer had long hair to wear them in.','Artık onları takabileceği uzun saçları olmasa da tarakları bağrına bastı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-23',23,'Trying to smile through her tears, she showed Jim the watch chain.','Gözyaşlarının arasından gülümsemeye çalışarak Jim''e saat zincirini gösterdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-24',24,'She asked him to take out his watch so they could try it.','Zinciri deneyebilmeleri için saatini çıkarmasını istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-25',25,'Jim sat down and suggested putting their presents away for a while.','Jim oturdu ve hediyelerini bir süreliğine kaldırmayı önerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-26',26,'He had sold his watch to buy the combs.','Tarakları almak için saatini satmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-27',27,'Each had given up a treasured possession to make the other happy.','Her biri, diğerini mutlu etmek için çok değer verdiği bir eşyasından vazgeçmişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-28',28,'Their gifts could not be used just then, but their love had become clear.','Hediyeleri o anda kullanılamıyordu ama sevgileri açıkça ortaya çıkmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-29',29,'The narrator compares them to the Magi, the wise visitors who brought gifts to the baby Jesus.','Anlatıcı onları, bebek İsa''ya hediyeler getiren bilge ziyaretçiler olan Müneccimlere benzetir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('01bf33c9-242c-5939-a594-c24dabe7e8de','cl-gift-magi-30',30,'Although their choices might look foolish, he calls them the wisest of gift-givers.','Seçimleri aptalca görünse de anlatıcı onları hediye verenlerin en bilgeleri olarak adlandırır.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','savings','savings','birikim','/ˈseɪvɪŋz/','Della counts her savings.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','wages','wages','ücret','/ˈweɪdʒɪz/','Jim''s wages have fallen.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','proud','proud','gururlu','/praʊd/','The crow feels proud.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','gold','gold','altın','/ɡəʊld/','He wants all the gold at once.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','inherited','inherited','miras aldı','/ɪnˈherɪtɪd/','Jim inherited a gold watch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','father','father','baba','/ˈfɑːðə(r)/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','mirror','mirror','ayna','/ˈmɪrə(r)/','The new queen asked her magic mirror who was the most beautiful.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','gift','gift','hediye','/ɡɪft/','Della wants to buy a gift.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','platinum','platinum','platin','/ˈplætɪnəm/','Della buys a platinum chain.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','chain','chain','zincir','/tʃeɪn/','The chain is for Jim''s watch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','combs','combs','taraklar','/kəʊmz/','Jim gives Della expensive combs.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','window','window','pencere','/ˈwɪndoʊ/','Anna looks out of her window.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','smile','smile','gülümsemek','/smaɪl/','She gave him a warm smile.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','tears','tears','gözyaşları','/tɪəz/','Her tears fell into his eyes, and he could see once more.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('01bf33c9-242c-5939-a594-c24dabe7e8de','possession','possession','eşya','/pəˈzeʃn/','Each gives up a treasured possession.');
