insert into public.content_assets(id,kind,storage_path,sha256,byte_size,mime_type) values('5443a02c-d2ad-5d38-ac61-b01a2a17d113','cover','covers/b030a3740534593b7b27fcab2548ab1c2e1f91bc2c2b8489497b8b1ede9ac88a.png','b030a3740534593b7b27fcab2548ab1c2e1f91bc2c2b8489497b8b1ede9ac88a',31204,'image/png') on conflict do nothing;
insert into public.stories(id) values('classic-after-twenty-years') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','classic-after-twenty-years',1,'After Twenty Years','O. Henry','B1','Gizem','Yirmi Yıl Sonra. Eski bir buluşma sözü, bir polis memurunu dostluk ile görevi arasında bırakır. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales.','5443a02c-d2ad-5d38-ac61-b01a2a17d113');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-01',1,'It was almost ten on a cold, rainy night in New York.','New York''ta soğuk ve yağmurlu bir gecede saat neredeyse ondu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-02',2,'A policeman was checking the doors of shops along a quiet street.','Bir polis memuru sessiz bir sokaktaki dükkânların kapılarını kontrol ediyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-03',3,'In a dark doorway, he noticed a man waiting with an unlit cigar.','Karanlık bir kapı aralığında, elinde yanmamış bir puroyla bekleyen bir adam fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-04',4,'The man quickly explained that he was keeping an appointment made twenty years earlier.','Adam, yirmi yıl önce kararlaştırılan bir buluşma için geldiğini hemen açıkladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-05',5,'A restaurant had once stood there, and he had eaten his last dinner in New York inside it.','Bir zamanlar orada bir restoran vardı ve adam New York''taki son akşam yemeğini orada yemişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-06',6,'His companion that evening had been his closest friend, Jimmy Wells.','O akşamki arkadaşı, en yakın dostu Jimmy Wells''ti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-07',7,'They had grown up together, almost like brothers.','Neredeyse kardeş gibi birlikte büyümüşlerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-08',8,'The next morning, the man had left for the West to seek his fortune.','Ertesi sabah adam servetini aramak için Batı''ya gitmişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-09',9,'Jimmy had preferred to stay in the city he loved.','Jimmy ise sevdiği şehirde kalmayı tercih etmişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-10',10,'Before parting, they had promised to meet at that exact place twenty years later.','Ayrılmadan önce yirmi yıl sonra tam o yerde buluşmaya söz vermişlerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-11',11,'They had exchanged letters for a while, but eventually lost contact.','Bir süre mektuplaşmışlar ama sonunda haberleşmeyi kesmişlerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-12',12,'Despite the silence, the waiting man was certain Jimmy would remember.','Aradan geçen sessiz yıllara rağmen bekleyen adam, Jimmy''nin hatırlayacağından emindi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-13',13,'He struck a match to light his cigar.','Purosunu yakmak için bir kibrit çaktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-14',14,'The flame revealed a small scar near his eyebrow and a large diamond on his tie.','Alev, kaşının yanındaki küçük bir yara izini ve kravatındaki büyük elması ortaya çıkardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-15',15,'He told the policeman that he had travelled a thousand miles for the meeting.','Polise bu buluşma için bin mil yol geldiğini söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-16',16,'After wishing him luck, the officer continued down the street.','Memur ona şans dileyip sokakta yürümeye devam etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-17',17,'About twenty minutes later, a tall man in a long coat arrived.','Yaklaşık yirmi dakika sonra uzun paltolu, uzun boylu bir adam geldi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-18',18,'He greeted the waiting man as Bob and behaved like an old friend.','Bekleyen adama Bob diye seslendi ve eski bir dost gibi davrandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-19',19,'Believing Jimmy had finally come, Bob warmly took his hands.','Jimmy''nin sonunda geldiğine inanan Bob, onun ellerini içtenlikle tuttu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-20',20,'They walked together while Bob described his successful life in the West.','Bob Batı''daki başarılı hayatını anlatırken birlikte yürüdüler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-21',21,'Under the bright lights of a shop, Bob suddenly looked closely at the other''s face.','Bir dükkânın parlak ışıkları altında Bob birden diğer adamın yüzüne dikkatle baktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-22',22,'The shape of his nose was different, and Bob realized he was not Jimmy.','Burnunun şekli farklıydı ve Bob onun Jimmy olmadığını fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-23',23,'The stranger explained that he was a plain-clothes detective.','Yabancı, sivil bir dedektif olduğunu açıkladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-24',24,'Bob was wanted by the police in Chicago, and he was now under arrest.','Bob Chicago polisi tarafından aranıyordu ve artık gözaltındaydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-25',25,'Before taking him to the station, the detective handed him a note from Jimmy Wells.','Dedektif onu karakola götürmeden önce Jimmy Wells''ten bir not verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-26',26,'In the note, Jimmy explained that he had reached their meeting place on time.','Jimmy notta buluşma yerine zamanında geldiğini açıklıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-27',27,'He was the first policeman who had spoken to Bob in the doorway.','Kapı aralığında Bob''la konuşan ilk polis oydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-28',28,'When the match lit Bob''s face, Jimmy had recognized a man wanted in Chicago.','Kibrit Bob''un yüzünü aydınlattığında Jimmy, Chicago''da aranan bir adamı tanımıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-29',29,'Unable to arrest his old friend himself, he had asked another officer to do it.','Eski dostunu kendisi gözaltına alamadığı için başka bir memurdan bunu yapmasını istemişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','cl-after-twenty-years-30',30,'Bob''s hand trembled as he finished reading the explanation.','Bob açıklamayı okumayı bitirdiğinde eli titredi.');
