insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','fortune','fortune','talih; servet','/ˈfɔːtʃuːn/','His greed has taken away his good fortune.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6f0016d0-54e8-5e5d-a74d-3b67976c4ba8','silence','silence','sessizlik','/ˈsaɪləns/','Elisa accepted the painful task and began to work in silence.');
