insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('fbab0020-bf68-5e77-a635-e638cfdf599b','classic-crow-pitcher',1,'The Crow and the Pitcher','Aesop','A1','Macera','Karga ve Sürahi. Susamış bir karga, suya ulaşmak için akıllıca bir yol bulur. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','9f4fee92-7115-530b-acc6-01c15f80aa76');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-01',1,'A thirsty crow looks for water.','Susamış bir karga su arar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-02',2,'She sees a pitcher near a house.','Bir evin yakınında bir sürahi görür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-03',3,'There is some water at the bottom.','Dibinde biraz su vardır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-04',4,'The crow puts her beak inside.','Karga gagasını içeri sokar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-05',5,'But she cannot reach the water.','Ama suya ulaşamaz.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-06',6,'She tries to push the pitcher over.','Sürahiyi devirmeye çalışır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-07',7,'It is too heavy to move.','Onu hareket ettirmek çok zordur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-08',8,'Then the crow notices some pebbles.','Sonra karga birkaç çakıl taşı fark eder.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-09',9,'She drops a pebble into the pitcher.','Sürahinin içine bir çakıl taşı atar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-10',10,'She adds more pebbles, one by one.','Teker teker daha fazla çakıl taşı ekler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-11',11,'Slowly, the water rises.','Su yavaşça yükselir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-12',12,'Now she can reach it with her beak.','Artık gagasıyla ona ulaşabilir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-13',13,'The crow drinks and flies away.','Karga su içer ve uçup gider.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fbab0020-bf68-5e77-a635-e638cfdf599b','cl-crow-pitcher-14',14,'A clever idea can solve a difficult problem.','Akıllıca bir fikir zor bir sorunu çözebilir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fbab0020-bf68-5e77-a635-e638cfdf599b','thirsty','thirsty','susamış','/ˈθɜːsti/','A thirsty crow looks for water.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fbab0020-bf68-5e77-a635-e638cfdf599b','crow','crow','karga','/krəʊ/','A thirsty crow looks for water.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fbab0020-bf68-5e77-a635-e638cfdf599b','pitcher','pitcher','sürahi','/ˈpɪtʃə(r)/','She sees a pitcher near a house.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fbab0020-bf68-5e77-a635-e638cfdf599b','beak','beak','gaga','/biːk/','The crow puts her beak inside.');
