insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','classic-boy-cried-wolf',1,'The Boy Who Cried Wolf','Aesop','A1','Günlük yaşam','Yalancı Çoban. Yalan yere yardım isteyen bir çoban, insanların güvenini kaybeder. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; koleksiyonun iç başlık sayfası, ayrı bir ilk baskı kapağı değildir.','684e76af-b38a-585b-a1fd-f65f2641f8de');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-01',1,'A shepherd boy watches sheep near a village.','Bir çoban çocuk, bir köyün yakınında koyunları gözetir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-02',2,'He is alone and wants some fun.','Yalnızdır ve biraz eğlenmek ister.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-03',3,'"Wolf! Wolf!" he shouts.','"Kurt! Kurt!" diye bağırır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-04',4,'The villagers run to help him.','Köylüler ona yardıma koşar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-05',5,'But there is no wolf.','Ama ortada kurt yoktur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-06',6,'The boy laughs at the villagers.','Çocuk köylülere güler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-07',7,'Later, he plays the same trick again.','Daha sonra aynı oyunu yine oynar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-08',8,'Again, the villagers come for nothing.','Köylüler yine boşuna gelir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-09',9,'One day, a real wolf arrives.','Bir gün gerçek bir kurt gelir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-10',10,'The frightened boy calls for help.','Korkmuş çocuk yardım ister.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-11',11,'This time, nobody comes.','Bu kez kimse gelmez.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-12',12,'The villagers do not believe him anymore.','Köylüler artık ona inanmaz.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-13',13,'The wolf attacks the sheep.','Kurt koyunlara saldırır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','cl-boy-cried-wolf-14',14,'A liar can lose people''s trust, even when he tells the truth.','Bir yalancı, doğruyu söylediğinde bile insanların güvenini kaybedebilir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','shepherd','shepherd','çoban','/ˈʃepəd/','A shepherd boy watches sheep near a village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','boy','boy','erkek çocuk, oğlan','/bɔɪ/','The boy plays in the park.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','sheep','sheep','koyunlar','/ʃiːp/','A shepherd boy watches sheep near a village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','village','village','köy','/ˈvɪlɪdʒ/','They visited a small village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','alone','alone','yalnız','/əˈloʊn/','He walks home alone.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('212a81c0-8dda-5e0f-a42e-fa434c880ae0','wolf','wolf','kurt','/wʊlf/','The wolf runs to the house.');
