insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','classic-town-country-mouse',1,'The Town Mouse and the Country Mouse','Aesop','A1','Macera','Şehir Faresi ile Kır Faresi. İki fare, zengin bir sofra ile huzurlu bir hayat arasında seçim yapar. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','c9ca9855-543c-5f65-ac94-e6f910c1016e');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-01',1,'A country mouse invites his town friend to dinner.','Bir kır faresi şehirli arkadaşını akşam yemeğine çağırır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-02',2,'He offers simple food from the fields.','Tarlalardan gelen basit yiyecekler sunar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-03',3,'The town mouse is not happy with the meal.','Şehir faresi yemekten memnun değildir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-04',4,'"Come to my house," he says.','"Benim evime gel," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-05',5,'"We have wonderful food there."','"Orada harika yiyeceklerimiz var."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-06',6,'The country mouse follows him to town.','Kır faresi onun peşinden şehre gider.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-07',7,'They find a table full of rich food.','Zengin yiyeceklerle dolu bir masa bulurlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-08',8,'But someone opens the door before they can eat.','Ama yiyemeden biri kapıyı açar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-09',9,'The mice run and hide in a hole.','Fareler koşup bir deliğe saklanır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-10',10,'When it is quiet, they come out again.','Ortalık sessizleşince yeniden çıkarlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-11',11,'Then another person enters, and they hide once more.','Sonra başka biri girer ve bir kez daha saklanırlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-12',12,'The country mouse decides to leave.','Kır faresi gitmeye karar verir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-13',13,'"Keep your fine food," he tells his friend.','Arkadaşına, "Güzel yiyeceklerin sende kalsın," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','cl-town-country-mouse-14',14,'"I prefer a simple meal and a safe home."','"Ben basit bir yemeği ve güvenli bir evi tercih ederim."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','country','country','kır; ülke','/ˈkʌntri/','A country mouse invites his town friend to dinner.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','mouse','mouse','fare','/maʊs/','The mouse is very small.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','dinner','dinner','akşam yemeği','/ˈdɪnə(r)/','A country mouse invites his town friend to dinner.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','food','food','yiyecek','/fuːd/','He offers simple food from the fields.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','meal','meal','öğün','/miːl/','The town mouse is not happy with the meal.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','rich','rich','zengin','/rɪtʃ/','They find a table full of rich food.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('8b9e1efd-c054-5a6d-a725-7dbd5716349c','mice','mice','fareler','/maɪs/','The mice run and hide in a hole.');
