insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','classic-north-wind-sun',1,'The North Wind and the Sun','Aesop','A1','Macera','Kuzey Rüzgârı ile Güneş. Bir yolcunun paltosu, güç ile nezaket arasındaki farkı gösterir. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','321a5723-2a53-5b46-a831-021f240d5f9a');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-01',1,'The North Wind and the Sun argue.','Kuzey Rüzgârı ile Güneş tartışır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-02',2,'Each thinks he is stronger.','Her biri kendisinin daha güçlü olduğunu düşünür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-03',3,'They see a traveler on the road.','Yolda bir yolcu görürler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-04',4,'He wears a warm coat.','Sıcak tutan bir palto giymektedir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-05',5,'"Let us make him take off his coat," says the Wind.','Rüzgâr, "Hadi ona paltosunu çıkarttıralım," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-06',6,'The Wind blows as hard as he can.','Rüzgâr elinden geldiğince sert eser.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-07',7,'The traveler pulls his coat closer.','Yolcu paltosuna daha sıkı sarılır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-08',8,'The Wind blows harder, but the coat stays on.','Rüzgâr daha sert eser ama palto adamın üzerinde kalır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-09',9,'At last, the Wind stops.','Sonunda Rüzgâr durur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-10',10,'Now the Sun shines gently.','Şimdi Güneş yumuşakça ışıldar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-11',11,'The traveler starts to feel warm.','Yolcu sıcaklamaya başlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-12',12,'Soon, he takes off his coat.','Çok geçmeden paltosunu çıkarır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-13',13,'The Sun wins without using force.','Güneş güç kullanmadan kazanır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','cl-north-wind-sun-14',14,'Gentleness can succeed where force fails.','Nezaket, gücün başarısız olduğu yerde başarılı olabilir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','north','north','kuzey','/nɔːθ/','The North Wind and the Sun argue.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','wind','wind','rüzgâr','/wɪnd/','The wind carried the boat.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','sun','sun','güneş','/sʌn/','The North Wind and the Sun argue.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','argue','argue','tartışmak','/ˈɑːɡjuː/','The North Wind and the Sun argue.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','stronger','stronger','daha güçlü','/ˈstrɒŋɡə(r)/','Each thinks he is stronger.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','traveler','traveler','yolcu','/ˈtrævələ(r)/','They see a traveler on the road.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','road','road','yol','/roʊd/','The road goes to the village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','coat','coat','palto','/koʊt/','His coat is wet.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','wins','wins','kazanır','/wɪnz/','Our team wins the game.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','force','force','güç; zor kullanma','/fɔːs/','The Sun wins without using force.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('fcad5cc5-79f4-5fd9-ac9d-777449728200','gentleness','gentleness','nezaket','/ˈdʒentlnəs/','Gentleness can succeed where force fails.');
