insert into public.stories(id) values('classic-golden-eggs') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','classic-golden-eggs',1,'The Hen and the Golden Eggs','Aesop','A1','Günlük yaşam','Altın Yumurtlayan Tavuk. Daha fazlasını isteyen bir adam, elindeki değerli şeyi kaybeder. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; koleksiyonun iç başlık sayfası, ayrı bir ilk baskı kapağı değildir.','684e76af-b38a-585b-a1fd-f65f2641f8de');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-01',1,'A man owns a special hen.','Bir adamın özel bir tavuğu vardır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-02',2,'Every day, she lays a golden egg.','Tavuk her gün altın bir yumurta yumurtlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-03',3,'The man sells the eggs and becomes rich.','Adam yumurtaları satar ve zengin olur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-04',4,'But one egg a day is not enough for him.','Ama günde bir yumurta ona yetmez.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-05',5,'He wants all the gold at once.','Bütün altını bir kerede ister.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-06',6,'"The gold must be inside the hen," he thinks.','"Altın tavuğun içinde olmalı," diye düşünür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-07',7,'He decides to kill her.','Onu öldürmeye karar verir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-08',8,'He opens her body and looks for the gold.','Vücudunu açar ve altını arar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-09',9,'But she is like any other hen inside.','Ama içi diğer tavuklarınki gibidir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-10',10,'There is no treasure to take.','Alınacak bir hazine yoktur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-11',11,'Now the man has no hen and no golden eggs.','Artık adamın ne tavuğu ne de altın yumurtaları vardır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','cl-golden-eggs-12',12,'His greed has taken away his good fortune.','Açgözlülüğü elindeki talihi yok etmiştir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','hen','hen','tavuk','/hen/','A man owns a special hen.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','golden','golden','altın; altından','/ˈɡəʊldən/','Every day, she lays a golden egg.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','egg','egg','yumurta','/eɡ/','Every day, she lays a golden egg.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','eggs','eggs','yumurtalar','/eɡz/','The man sells the eggs and becomes rich.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','rich','rich','zengin','/rɪtʃ/','They find a table full of rich food.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','gold','gold','altın','/ɡəʊld/','He wants all the gold at once.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','greed','greed','açgözlülük','/ɡriːd/','His greed has taken away his good fortune.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4b22c7c8-09f7-5f65-aaae-7fe19df75b18','fortune','fortune','talih; servet','/ˈfɔːtʃuːn/','His greed has taken away his good fortune.');
