insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','classic-dog-shadow',1,'The Dog and the Shadow','Aesop','A1','Macera','Köpek ve Gölgesi. Sudaki yansımasını başka bir köpek sanan açgözlü bir köpek. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','3ae02e44-c3e6-50eb-a768-64f3ebc47bde');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-01',1,'A dog carries a piece of meat in his mouth.','Bir köpek ağzında bir parça et taşır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-02',2,'He walks across a bridge over a river.','Bir nehrin üzerindeki köprüden geçer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-03',3,'When he looks down, he sees his reflection.','Aşağı baktığında kendi yansımasını görür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-04',4,'He thinks another dog is in the water.','Suyun içinde başka bir köpek olduğunu sanır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-05',5,'That dog seems to have a bigger piece of meat.','O köpeğin daha büyük bir et parçası var gibidir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-06',6,'The dog wants both pieces for himself.','Köpek iki parçayı da kendisi ister.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-07',7,'He opens his mouth to take the other piece.','Öteki parçayı almak için ağzını açar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-08',8,'His own meat falls into the river.','Kendi eti nehre düşer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-09',9,'The water carries it away.','Su onu alıp götürür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-10',10,'There is no second dog and no second piece of meat.','İkinci bir köpek ve ikinci bir et parçası yoktur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-11',11,'The dog is left with nothing.','Köpeğin elinde hiçbir şey kalmaz.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','cl-dog-shadow-12',12,'Wanting too much can make us lose what we have.','Çok fazlasını istemek, elimizdekini kaybetmemize yol açabilir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','dog','dog','köpek','/dɒɡ/','A dog carries a piece of meat in his mouth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','carries','carries','taşır','/ˈkæriz/','He carries a big box.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','meat','meat','et','/miːt/','A dog carries a piece of meat in his mouth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','mouth','mouth','ağız','/maʊθ/','A dog carries a piece of meat in his mouth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','bridge','bridge','köprü','/brɪdʒ/','They crossed the bridge.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','river','river','nehir','/ˈrɪvər/','The river moved slowly.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','reflection','reflection','yansıma','/rɪˈflekʃn/','When he looks down, he sees his reflection.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','bigger','bigger','daha büyük','/ˈbɪɡər/','My room is bigger than yours.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','pieces','pieces','parçalar','/ˈpiːsɪz/','She cuts the bread into small pieces.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','own','own','kendi','/oʊn/','She has her own room.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','second','second','ikinci','/ˈsekənd/','This is my second visit.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','nothing','nothing','hiçbir şey','/ˈnʌθɪŋ/','There is nothing in the box.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('1215148a-d1eb-59b0-a74b-d61ae69588cb','much','much','çok','/mʌtʃ/','Thank you very much.');
