insert into public.stories(id) values('classic-fox-crow') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','classic-fox-crow',1,'The Fox and the Crow','Aesop','A1','Macera','Tilki ile Karga. Güzel sözlere kanan bir karganın elinden düşürdüğü yiyecek. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','ac864d31-6910-566d-a97d-ca0be86a85e0');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-01',1,'A crow sits on a branch with a piece of meat.','Bir karga, gagasında bir parça etle bir dalda oturur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-02',2,'A fox sees the meat and wants it.','Bir tilki eti görür ve onu ister.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-03',3,'He cannot climb up to take it.','Onu almak için yukarı tırmanamaz.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-04',4,'So he begins to praise the crow.','Bu yüzden kargayı övmeye başlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-05',5,'"What beautiful feathers you have!" he says.','"Ne güzel tüylerin var!" der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-06',6,'"You must have a beautiful voice, too."','"Sesin de güzel olmalı."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-07',7,'The crow feels proud.','Karga gururlanır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-08',8,'She wants to show him her voice.','Ona sesini göstermek ister.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-09',9,'She opens her beak and makes a loud sound.','Gagasını açar ve yüksek bir ses çıkarır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-10',10,'The meat falls to the ground.','Et yere düşer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-11',11,'The fox picks it up and laughs.','Tilki onu alır ve güler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-12',12,'"You have a voice, but you need more sense," he says.','"Sesin var ama daha akıllı olman gerekiyor," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-13',13,'The crow watches him leave with her meal.','Karga, tilkinin yemeğiyle uzaklaşmasını izler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','cl-fox-crow-14',14,'Flattery is not always friendship.','Pohpohlamak her zaman dostluk değildir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','crow','crow','karga','/krəʊ/','A thirsty crow looks for water.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','meat','meat','et','/miːt/','A dog carries a piece of meat in his mouth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','fox','fox','tilki','/fɒks/','The fox sees some grapes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','praise','praise','övmek','/preɪz/','So he begins to praise the crow.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','feathers','feathers','tüyler','/ˈfeðəz/','"What beautiful feathers you have!" he says.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','voice','voice','ses','/vɔɪs/','"You must have a beautiful voice, too."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','proud','proud','gururlu','/praʊd/','The crow feels proud.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','beak','beak','gaga','/biːk/','The crow puts her beak inside.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','laughs','laughs','güler','/læfs/','She laughs at the funny story.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','sense','sense','akıl; sağduyu','/sens/','"You have a voice, but you need more sense," he says.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','meal','meal','öğün','/miːl/','The town mouse is not happy with the meal.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dd1c39e1-75eb-572c-a4da-634c2adebaef','flattery','flattery','pohpohlama','/ˈflætəri/','Flattery is not always friendship.');
