insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('08e2642c-020a-58e7-a227-28cd678aae69','classic-ant-dove',1,'The Ant and the Dove','Aesop','A1','Macera','Karınca ile Güvercin. Bir güvercin ile bir karınca, birbirlerinin hayatını kurtarır. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; koleksiyonun iç başlık sayfası, ayrı bir ilk baskı kapağı değildir.','684e76af-b38a-585b-a1fd-f65f2641f8de');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-01',1,'An ant goes to a river to drink.','Bir karınca su içmek için nehre gider.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-02',2,'She slips and falls into the water.','Ayağı kayar ve suya düşer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-03',3,'The current carries her away.','Akıntı onu sürükler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-04',4,'A dove sees the ant from a tree.','Bir güvercin karıncayı ağaçtan görür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-05',5,'He drops a leaf into the river.','Nehre bir yaprak bırakır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-06',6,'The ant climbs onto the leaf.','Karınca yaprağın üzerine çıkar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-07',7,'Soon, she reaches the bank safely.','Çok geçmeden güvenle kıyıya ulaşır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-08',8,'Later, a hunter gets ready to catch the dove.','Daha sonra bir avcı güvercini yakalamaya hazırlanır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-09',9,'The ant sees him and runs to his foot.','Karınca onu görür ve ayağına koşar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-10',10,'She bites his heel.','Topuğunu ısırır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-11',11,'The hunter cries out and drops his trap.','Avcı bağırır ve tuzağını düşürür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-12',12,'The dove hears him and flies away.','Güvercin onu duyar ve uçup gider.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('08e2642c-020a-58e7-a227-28cd678aae69','cl-ant-dove-13',13,'Both friends are safe because they help each other.','İki dost birbirlerine yardım ettikleri için güvendedir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','ant','ant','karınca','/ænt/','An ant goes to a river to drink.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','river','river','nehir','/ˈrɪvər/','The river moved slowly.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','current','current','akıntı','/ˈkʌrənt/','The current carries her away.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','carries','carries','taşır','/ˈkæriz/','He carries a big box.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','dove','dove','güvercin','/dʌv/','A dove sees the ant from a tree.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','leaf','leaf','yaprak','/liːf/','He drops a leaf into the river.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','bank','bank','nehir kıyısı','/bæŋk/','Soon, she reaches the bank safely.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','safely','safely','güvenli bir şekilde','/ˈseɪfli/','He put the ticket safely in his pocket.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','hunter','hunter','avcı','/ˈhʌntə(r)/','A hunter hears the noise.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','bites','bites','ısırır','/baɪts/','The small dog bites the toy.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','heel','heel','topuk','/hiːl/','She bites his heel.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','trap','trap','tuzak','/træp/','The hunter cries out and drops his trap.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('08e2642c-020a-58e7-a227-28cd678aae69','safe','safe','güvenli','/seɪf/','"I prefer a simple meal and a safe home."');
