insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('dfafbbfc-5ac2-5326-af9e-85626b020562','classic-bundle-sticks',1,'The Bundle of Sticks','Aesop','A1','Günlük yaşam','Bir Demet Çubuk. Bir baba, sürekli tartışan oğullarına birlikte olmanın gücünü gösterir. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; koleksiyonun iç başlık sayfası, ayrı bir ilk baskı kapağı değildir.','684e76af-b38a-585b-a1fd-f65f2641f8de');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-01',1,'A father has several sons.','Bir babanın birkaç oğlu vardır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-02',2,'They often argue with each other.','Birbirleriyle sık sık tartışırlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-03',3,'Their father wants them to live in peace.','Babaları onların barış içinde yaşamasını ister.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-04',4,'One day, he brings them a bundle of sticks.','Bir gün onlara bir demet çubuk getirir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-05',5,'"Try to break this bundle," he says.','"Bu demeti kırmayı deneyin," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-06',6,'Each son tries, but nobody can break it.','Her oğul dener ama hiçbiri onu kıramaz.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-07',7,'Then the father unties the bundle.','Sonra baba demetin bağını çözer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-08',8,'He gives each son a single stick.','Her oğluna tek bir çubuk verir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-09',9,'Now they break the sticks easily.','Şimdi çubukları kolayca kırarlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-10',10,'"Together, you are strong like the bundle," says their father.','Babaları, "Birlikteyken bu demet gibi güçlüsünüz," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-11',11,'"Alone, each of you is easy to hurt."','"Yalnızken her birinizi incitmek kolaydır."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-12',12,'The sons listen to his lesson.','Oğullar babalarının verdiği dersi dinler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('dfafbbfc-5ac2-5326-af9e-85626b020562','cl-bundle-sticks-13',13,'People are stronger when they stand together.','İnsanlar birlikte durduklarında daha güçlüdür.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','father','father','baba','/ˈfɑːðə(r)/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','sons','sons','oğullar','/sʌnz/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','argue','argue','tartışmak','/ˈɑːɡjuː/','The North Wind and the Sun argue.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','peace','peace','barış; huzur','/piːs/','Their father wants them to live in peace.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','bundle','bundle','demet','/ˈbʌndl/','One day, he brings them a bundle of sticks.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','sticks','sticks','çubuklar','/stɪks/','One day, he brings them a bundle of sticks.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','break','break','kırmak','/breɪk/','"Try to break this bundle," he says.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','tries','tries','dener','/traɪz/','He tries to open the door.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','nobody','nobody','hiç kimse','/ˈnoʊbədi/','Nobody is at home today.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','single','single','tek','/ˈsɪŋɡl/','He gives each son a single stick.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','strong','strong','güçlü, sağlam','/strɔːŋ/','This bag is strong.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','alone','alone','yalnız','/əˈloʊn/','He walks home alone.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('dfafbbfc-5ac2-5326-af9e-85626b020562','stronger','stronger','daha güçlü','/ˈstrɒŋɡə(r)/','Each thinks he is stronger.');
