insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','classic-milkmaid-pail',1,'The Milkmaid and Her Pail','Aesop','A1','Günlük yaşam','Sütçü Kız ve Kovası. Gelecekteki kazancını hayal eden bir kız, elindeki sütü unutur. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; koleksiyonun iç başlık sayfası, ayrı bir ilk baskı kapağı değildir.','684e76af-b38a-585b-a1fd-f65f2641f8de');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-01',1,'A milkmaid walks to the market.','Bir sütçü kız pazara yürür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-02',2,'She carries a pail of milk on her head.','Başında bir kova süt taşır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-03',3,'She thinks about the money she can earn.','Kazanabileceği parayı düşünür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-04',4,'"I can buy eggs with the money," she thinks.','"Parayla yumurta alabilirim," diye düşünür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-05',5,'"The eggs can become chickens."','"Yumurtalardan tavuklar çıkabilir."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-06',6,'"Then I can sell the chickens and buy a fine dress."','"Sonra tavukları satıp güzel bir elbise alabilirim."');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-07',7,'She imagines people admiring her new clothes.','İnsanların yeni kıyafetlerine hayran kaldığını hayal eder.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-08',8,'She imagines turning her head proudly.','Başını gururla çevirdiğini hayal eder.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-09',9,'As she dreams, she moves her real head.','Hayal kurarken gerçekten de başını oynatır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-10',10,'The pail falls to the ground.','Kova yere düşer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-11',11,'All the milk spills out.','Bütün süt dökülür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-12',12,'Her money, chickens, and dress disappear with it.','Parası, tavukları ve elbisesi de sütle birlikte yok olur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','cl-milkmaid-pail-13',13,'Plans need care before they can become real.','Planların gerçekleşebilmesi için önce özen göstermek gerekir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','milkmaid','milkmaid','sütçü kız','/ˈmɪlkmeɪd/','A milkmaid walks to the market.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','market','market','pazar','/ˈmɑːrkɪt/','The market was busy.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','carries','carries','taşır','/ˈkæriz/','He carries a big box.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','pail','pail','kova','/peɪl/','She carries a pail of milk on her head.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','money','money','para','/ˈmʌni/','She thinks about the money she can earn.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','earn','earn','kazanmak','/ɜːn/','She thinks about the money she can earn.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','eggs','eggs','yumurtalar','/eɡz/','The man sells the eggs and becomes rich.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('3f8d7e9c-8d0f-53b3-a770-2ff4127a2984','chickens','chickens','tavuklar','/ˈtʃɪkɪnz/','"The eggs can become chickens."');
