insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('184110f8-c35f-5b57-a481-700e5142c774','classic-dog-manger',1,'The Dog in the Manger','Aesop','A1','Macera','Yemlikteki Köpek. Kendisine yaramayan otu başkalarıyla paylaşmayan bir köpek. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','f4d16f53-1c62-5f28-a5ff-14daf3ae7f28');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-01',1,'A dog lies in a manger full of hay.','Bir köpek ot dolu bir yemliğe uzanır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-02',2,'The hay is soft, and he falls asleep.','Ot yumuşaktır ve köpek uykuya dalar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-03',3,'Some oxen come back from their work.','Birkaç öküz işten döner.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-04',4,'They are tired and hungry.','Yorgun ve açtırlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-05',5,'They want to eat the hay.','Otu yemek isterler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-06',6,'The dog wakes up and starts to bark.','Köpek uyanır ve havlamaya başlar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-07',7,'He will not let the oxen come near.','Öküzlerin yaklaşmasına izin vermez.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-08',8,'But the dog cannot eat hay himself.','Oysa köpeğin kendisi ot yiyemez.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-09',9,'The oxen look at him in surprise.','Öküzler ona şaşkınlıkla bakar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-10',10,'"You do not want this food," one says.','İçlerinden biri, "Sen bu yiyeceği istemiyorsun," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-11',11,'"Why stop us from eating it?"','"Neden bizim yememizi engelliyorsun?"');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('184110f8-c35f-5b57-a481-700e5142c774','cl-dog-manger-12',12,'Keeping others from something we cannot use is selfish.','Kullanamadığımız bir şeyi başkalarından esirgemek bencilliktir.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','dog','dog','köpek','/dɒɡ/','A dog carries a piece of meat in his mouth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','manger','manger','yemlik','/ˈmeɪndʒə(r)/','A dog lies in a manger full of hay.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','hay','hay','kuru ot','/heɪ/','A dog lies in a manger full of hay.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','oxen','oxen','öküzler','/ˈɒksn/','Some oxen come back from their work.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','tired','tired','yorgun','/ˈtaɪərd/','She is tired after work.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','hungry','hungry','aç','/ˈhʌŋɡri/','I am hungry after school.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','bark','bark','havlamak','/bɑːk/','The dog wakes up and starts to bark.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','food','food','yiyecek','/fuːd/','He offers simple food from the fields.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('184110f8-c35f-5b57-a481-700e5142c774','selfish','selfish','bencil','/ˈselfɪʃ/','The selfish giant builds a wall.');
