insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','classic-ass-lion-skin',1,'The Ass in the Lion’s Skin','Aesop','A1','Macera','Aslan Postundaki Eşek. Bir aslan postu, eşeğin sesini değiştirmeye yetmez. A1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','8653b468-5ed8-564e-a6d2-003cfc7adbda');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-01',1,'An ass finds a lion''s skin.','Bir eşek bir aslan postu bulur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-02',2,'He puts it over his body.','Postu vücudunun üzerine geçirir.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-03',3,'Now he looks like a big lion.','Artık büyük bir aslana benzer.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-04',4,'He walks around and frightens the animals.','Dolaşarak hayvanları korkutur.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-05',5,'They all run away from him.','Hepsi ondan kaçar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-06',6,'The ass feels very proud.','Eşek çok gururlanır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-07',7,'Then he sees a fox.','Sonra bir tilki görür.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-08',8,'He tries to frighten her, too.','Onu da korkutmaya çalışır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-09',9,'But he opens his mouth and brays.','Ama ağzını açar ve anırır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-10',10,'The fox knows that sound at once.','Tilki o sesi hemen tanır.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-11',11,'"Your clothes are a lion''s, but your voice is an ass''s," she says.','"Kıyafetin aslanınki ama sesin bir eşeğin," der.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','cl-ass-lion-skin-12',12,'A fine disguise cannot hide who we are forever.','Güzel bir kılık, kim olduğumuzu sonsuza kadar gizleyemez.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','ass','ass','eşek','/æs/','An ass finds a lion''s skin.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','skin','skin','deri; post','/skɪn/','An ass finds a lion''s skin.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','lion','lion','aslan','/ˈlaɪən/','The lion sleeps under a tree.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','animals','animals','hayvanlar','/ˈænɪmlz/','He walks around and frightens the animals.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','proud','proud','gururlu','/praʊd/','The crow feels proud.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','fox','fox','tilki','/fɒks/','The fox sees some grapes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','tries','tries','dener','/traɪz/','He tries to open the door.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','mouth','mouth','ağız','/maʊθ/','A dog carries a piece of meat in his mouth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','brays','brays','anırır','/breɪz/','But he opens his mouth and brays.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','voice','voice','ses','/vɔɪs/','"You must have a beautiful voice, too."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('9ecc234b-1c7b-5147-a141-b50bbde9d3a7','disguise','disguise','kılık','/dɪsˈɡaɪz/','A fine disguise cannot hide who we are forever.');
