insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','classic-snow-white',1,'Snow White','Jacob and Wilhelm Grimm','A2','Macera','Pamuk Prenses. Kıskanç bir kraliçe, sihirli ayna ve ormanda yaşayan yedi cüce. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','30933df1-a5b9-54ac-a150-cf29c1ba9065');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-01',1,'A queen had a daughter with skin as white as snow and hair as black as ebony.','Bir kraliçenin teni kar gibi beyaz, saçları abanoz gibi siyah bir kızı vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-02',2,'After the queen died, the king married another woman.','Kraliçe öldükten sonra kral başka bir kadınla evlendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-03',3,'The new queen asked her magic mirror who was the most beautiful.','Yeni kraliçe sihirli aynasına en güzelin kim olduğunu soruyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-04',4,'For years, the mirror answered that she was.','Ayna yıllarca en güzelin o olduğu cevabını verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-05',5,'Then one day, it named Snow White instead.','Sonra bir gün onun yerine Pamuk Prenses''in adını söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-06',6,'The jealous queen ordered a hunter to kill the girl.','Kıskanç kraliçe bir avcıya kızı öldürmesini emretti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-07',7,'But the hunter let her escape into the forest.','Ama avcı onun ormana kaçmasına izin verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-08',8,'Snow White found a small house and fell asleep inside.','Pamuk Prenses küçük bir ev buldu ve içeride uyuyakaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-09',9,'Seven dwarfs lived there and agreed to let her stay.','Orada yedi cüce yaşıyordu ve kızın kalmasına izin verdiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-10',10,'They warned her not to open the door to strangers.','Yabancılara kapıyı açmaması için onu uyardılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-11',11,'The mirror told the queen that Snow White was still alive.','Ayna kraliçeye Pamuk Prenses''in hâlâ hayatta olduğunu söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-12',12,'Disguised as a seller, she visited the house and tied the girl''s laces too tightly.','Satıcı kılığına girerek evi ziyaret etti ve kızın bağcıklarını çok sıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-13',13,'The dwarfs returned and loosened the laces in time to save her.','Cüceler dönüp onu kurtaracak kadar erken bağcıkları gevşetti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-14',14,'The queen tried again with a poisoned comb, but the dwarfs removed it.','Kraliçe zehirli bir tarakla yeniden denedi ama cüceler tarağı çıkardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-15',15,'Finally, she gave Snow White a poisoned apple.','Sonunda Pamuk Prenses''e zehirli bir elma verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-16',16,'This time, the dwarfs could not wake the girl and placed her in a glass coffin.','Cüceler bu kez kızı uyandıramadı ve onu cam bir tabuta koydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-17',17,'A prince saw her and asked to take the coffin with him.','Bir prens onu gördü ve tabutu yanında götürmek istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-18',18,'As his servants carried it, they stumbled and the piece of apple came out of her throat.','Hizmetkârları tabutu taşırken tökezledi ve elma parçası kızın boğazından çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-19',19,'Snow White woke up and later married the prince.','Pamuk Prenses uyandı ve daha sonra prensle evlendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','cl-snow-white-20',20,'The queen came to the wedding, where she was punished for her cruelty.','Kraliçe düğüne geldi ve orada zalimliği yüzünden cezalandırıldı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','queen','queen','kraliçe','/kwiːn/','A queen had a daughter with skin as white as snow and hair as black as ebony.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','skin','skin','deri; post','/skɪn/','An ass finds a lion''s skin.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','married','married','evlendi','/ˈmærid/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','magic','magic','sihirli','/ˈmædʒɪk/','The new queen asked her magic mirror who was the most beautiful.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','mirror','mirror','ayna','/ˈmɪrə(r)/','The new queen asked her magic mirror who was the most beautiful.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','hunter','hunter','avcı','/ˈhʌntə(r)/','A hunter hears the noise.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','forest','forest','orman','/ˈfɔːrɪst/','The forest was full of birds.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
