insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','strangers','strangers','yabancılar','/ˈstreɪndʒəz/','They warned her not to open the door to strangers.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','poisoned','poisoned','zehirli','/ˈpɔɪznd/','The queen tried again with a poisoned comb, but the dwarfs removed it.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('ba89341b-aa17-5f66-ab80-ecb4f1239542','coffin','coffin','tabut','/ˈkɒfɪn/','This time, the dwarfs could not wake the girl and placed her in a glass coffin.');
