insert into public.stories(id) values('classic-rapunzel') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','classic-rapunzel',1,'Rapunzel','Jacob and Wilhelm Grimm','A2','Macera','Rapunzel. Yüksek bir kuleye kapatılan uzun saçlı bir kızın özgürlüğe kavuşması. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','98c31786-4e0c-5753-ab54-587ef53f6230');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-01',1,'A woman longed to eat the green plants in a nearby garden.','Bir kadın yakındaki bir bahçede yetişen yeşil bitkilerden yemeyi çok istiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-02',2,'Her husband climbed over the wall and took some for her.','Kocası duvarı aşıp onun için biraz topladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-03',3,'The enchantress who owned the garden caught him on his next visit.','Bahçenin sahibi olan büyücü kadın, sonraki gelişinde adamı yakaladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-04',4,'She let him go only after he promised her his coming child.','Adamı ancak doğacak çocuğunu kendisine vereceğine söz verdikten sonra bıraktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-05',5,'When a baby girl was born, the enchantress took her and named her Rapunzel.','Bir kız bebek doğduğunda büyücü kadın onu alıp Rapunzel adını verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-06',6,'At twelve, Rapunzel was shut in a tower with no stairs or door.','Rapunzel on iki yaşındayken merdiveni ve kapısı olmayan bir kuleye kapatıldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-07',7,'The enchantress called from below, and Rapunzel let down her long hair.','Büyücü kadın aşağıdan sesleniyor, Rapunzel de uzun saçlarını sarkıtıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-08',8,'Then the woman climbed up the hair to the window.','Sonra kadın saçlara tutunarak pencereye tırmanıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-09',9,'One day, a prince heard Rapunzel singing and found the tower.','Bir gün bir prens Rapunzel''in şarkısını duyup kuleyi buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-10',10,'He watched how the enchantress entered, then tried the same call.','Büyücü kadının nasıl girdiğini izledi, sonra aynı şekilde seslenmeyi denedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-11',11,'Rapunzel was frightened at first, but soon wanted to marry him.','Rapunzel önce korktu ama kısa süre sonra onunla evlenmek istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-12',12,'They planned to make a ladder of silk so that she could escape.','Kaçabilmesi için ipekten bir merdiven yapmayı planladılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-13',13,'But Rapunzel accidentally revealed the prince''s visits to the enchantress.','Ama Rapunzel yanlışlıkla prensin ziyaretlerini büyücü kadına belli etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-14',14,'The angry woman cut off her hair and sent her to a lonely wilderness.','Öfkeli kadın kızın saçlarını kesip onu ıssız bir yere gönderdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-15',15,'When the prince returned, the enchantress waited in the tower with the cut hair.','Prens döndüğünde büyücü kadın kesilmiş saçlarla kulede bekliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-16',16,'In despair, he jumped from the tower and thorns injured his eyes.','Prens umutsuzluk içinde kuleden atladı ve dikenler gözlerini yaraladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-17',17,'Blind and unhappy, he wandered for years until he heard Rapunzel''s voice again.','Kör ve mutsuz hâlde yıllarca dolaştıktan sonra Rapunzel''in sesini yeniden duydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-18',18,'She was living with their twins, a boy and a girl.','Rapunzel, bir kız bir erkek olan ikiz çocuklarıyla yaşıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-19',19,'Her tears fell into his eyes, and he could see once more.','Kızın gözyaşları prensin gözlerine düştü ve prens yeniden görebildi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','cl-rapunzel-20',20,'He took his family home to his kingdom, where they lived happily.','Ailesini krallığındaki evine götürdü ve orada mutlu yaşadılar.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','enchantress','enchantress','büyücü kadın','/ɪnˈtʃɑːntrəs/','The enchantress who owned the garden caught him on his next visit.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','tower','tower','kule','/ˈtaʊə(r)/','At twelve, Rapunzel was shut in a tower with no stairs or door.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','window','window','pencere','/ˈwɪndoʊ/','Anna looks out of her window.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','frightened','frightened','korkmuş','/ˈfraɪtnd/','The frightened cat hides under the bed.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','ladder','ladder','merdiven','/ˈlædə(r)/','They planned to make a ladder of silk so that she could escape.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','silk','silk','ipek','/sɪlk/','They planned to make a ladder of silk so that she could escape.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','thorns','thorns','dikenler','/θɔːnz/','In despair, he jumped from the tower and thorns injured his eyes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','blind','blind','kör','/blaɪnd/','Blind and unhappy, he wandered for years until he heard Rapunzel''s voice again.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','voice','voice','ses','/vɔɪs/','"You must have a beautiful voice, too."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','twins','twins','ikizler','/twɪnz/','She was living with their twins, a boy and a girl.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','boy','boy','erkek çocuk, oğlan','/bɔɪ/','The boy plays in the park.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('659a1edd-bad3-54d3-a03b-7ee99db8efa7','tears','tears','gözyaşları','/tɪəz/','Her tears fell into his eyes, and he could see once more.');
