insert into public.content_assets(id,kind,storage_path,sha256,byte_size,mime_type) values('392bb09d-3da8-54a0-ae30-ea15fc3a4bcd','cover','covers/d209dd2eca30ff7454b9971020196eb0d97697e8fc8bf002bd1d830eb7c51dd8.png','d209dd2eca30ff7454b9971020196eb0d97697e8fc8bf002bd1d830eb7c51dd8',756562,'image/png') on conflict do nothing;
insert into public.stories(id) values('classic-sleeping-beauty') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','classic-sleeping-beauty',1,'Sleeping Beauty','Jacob and Wilhelm Grimm','A2','Macera','Uyuyan Güzel. Yüz yıllık bir uykuya dalan prensesin eski Grimm anlatısı. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','392bb09d-3da8-54a0-ae30-ea15fc3a4bcd');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-01',1,'A king and queen were delighted when their daughter was born.','Bir kral ile kraliçe, kızları doğduğunda çok sevindi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-02',2,'They invited twelve wise women to a great celebration.','On iki bilge kadını büyük bir kutlamaya davet ettiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-03',3,'But there were thirteen wise women, and the last one was not invited.','Oysa on üç bilge kadın vardı ve sonuncusu davet edilmemişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-04',4,'She arrived in anger and placed a curse on the princess.','Kadın öfkeyle geldi ve prensesi lanetledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-05',5,'At fifteen, the girl would prick her finger on a spindle and die.','Kız on beş yaşında parmağına iğ değmesi sonucu ölecekti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-06',6,'The last invited woman could not remove the curse, but she softened it.','Davetli son kadın laneti kaldıramadı ama hafifletti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-07',7,'The princess would sleep for a hundred years instead.','Prenses bunun yerine yüz yıl uyuyacaktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-08',8,'The king ordered every spindle in the kingdom to be destroyed.','Kral, krallıktaki bütün iğlerin yok edilmesini emretti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-09',9,'On her fifteenth birthday, the princess explored an old tower.','Prenses on beşinci doğum gününde eski bir kuleyi keşfe çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-10',10,'Inside, an old woman was spinning with a spindle.','İçeride yaşlı bir kadın iğle iplik eğiriyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-11',11,'The princess touched it, hurt her finger, and fell asleep.','Prenses ona dokundu, parmağını yaraladı ve uykuya daldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-12',12,'Everyone in the castle fell asleep with her.','Şatodaki herkes de onunla birlikte uykuya daldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-13',13,'A thick hedge of thorns grew around the castle.','Şatonun çevresinde sık bir dikenli çit büyüdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-14',14,'Many princes tried to get through, but the thorns trapped them.','Birçok prens içeri geçmeye çalıştı ama dikenlere yakalandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-15',15,'After a hundred years, another prince heard the story of Briar-Rose.','Yüz yıl sonra başka bir prens, Dikenli Gül''ün hikâyesini duydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-16',16,'When he reached the hedge, the thorns had become flowers.','Prens çite ulaştığında dikenler çiçeklere dönüşmüştü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-17',17,'He walked into the silent castle and found the sleeping princess.','Sessiz şatoya girip uyuyan prensesi buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-18',18,'As he kissed her, she opened her eyes.','Prens onu öptüğünde kız gözlerini açtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-19',19,'The whole castle woke up and continued its interrupted day.','Bütün şato uyanıp yarım kalan gününe devam etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','cl-sleeping-beauty-20',20,'Soon, the prince and princess celebrated their wedding.','Çok geçmeden prens ile prenses düğünlerini kutladı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','queen','queen','kraliçe','/kwiːn/','A queen had a daughter with skin as white as snow and hair as black as ebony.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','curse','curse','lanet','/kɜːs/','She arrived in anger and placed a curse on the princess.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','princess','princess','prenses','/ˌprɪnˈses/','She arrived in anger and placed a curse on the princess.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','spindle','spindle','iğ','/ˈspɪndl/','At fifteen, the girl would prick her finger on a spindle and die.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','tower','tower','kule','/ˈtaʊə(r)/','At twelve, Rapunzel was shut in a tower with no stairs or door.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','spinning','spinning','iplik eğirme','/ˈspɪnɪŋ/','Inside, an old woman was spinning with a spindle.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','castle','castle','şato','/ˈkɑːsl/','Everyone in the castle fell asleep with her.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','thorns','thorns','dikenler','/θɔːnz/','In despair, he jumped from the tower and thorns injured his eyes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('5116cac4-6caf-5aa5-a0f7-6754429293f8','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
