insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('70e67693-3279-5f74-a92d-0c197068b4c9','classic-frog-prince',1,'The Frog Prince','Jacob and Wilhelm Grimm','A2','Macera','Kurbağa Prens. Bir kuyuya düşen altın top, prensesi verdiği sözle yüzleştirir. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','88b03939-3b81-505b-a5f3-cf4040673f78');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-01',1,'A princess loved to play with her golden ball near a deep well.','Bir prenses derin bir kuyunun yanında altın topuyla oynamayı severdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-02',2,'One day, the ball fell into the water, and she began to cry.','Bir gün top suya düştü ve kız ağlamaya başladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-03',3,'A frog offered to bring it back if she would become his friend.','Bir kurbağa, kendisine arkadaş olursa topu geri getirmeyi teklif etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-04',4,'He wanted to eat from her plate and sleep in her room.','Onun tabağından yemek ve odasında uyumak istiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-05',5,'She agreed, thinking that a frog could never really live with her.','Bir kurbağanın gerçekten kendisiyle yaşayamayacağını düşünerek kabul etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-06',6,'The frog fetched the ball, but the princess ran home without him.','Kurbağa topu getirdi ama prenses onu bırakıp eve koştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-07',7,'The next day, he arrived at the palace and knocked on the door.','Ertesi gün kurbağa saraya gelip kapıyı çaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-08',8,'The king asked his daughter what had happened.','Kral kızına ne olduğunu sordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-09',9,'When he heard her promise, he told her to keep it.','Verdiği sözü duyunca ona sözünü tutmasını söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-10',10,'Unhappily, she let the frog sit beside her and eat from her plate.','Kız istemeye istemeye kurbağanın yanına oturup tabağından yemesine izin verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-11',11,'After dinner, the frog wanted to rest in her room.','Yemekten sonra kurbağa kızın odasında dinlenmek istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-12',12,'The princess carried him upstairs but left him on the floor.','Prenses onu üst kata taşıdı ama yere bıraktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-13',13,'He insisted on coming into her bed and threatened to tell the king.','Kurbağa yatağa gelmekte ısrar etti ve krala söylemekle tehdit etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-14',14,'Angry and frightened, she threw him against the wall.','Öfkelenip korkan kız onu duvara fırlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-15',15,'When he fell, he had changed into a prince.','Yere düştüğünde bir prense dönüşmüştü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-16',16,'He explained that a witch had turned him into a frog.','Bir cadının kendisini kurbağaya dönüştürdüğünü açıkladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-17',17,'The king agreed that the two should marry.','Kral ikisinin evlenmesini kabul etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-18',18,'A carriage arrived with the prince''s loyal servant, Iron Henry.','Prensin sadık hizmetkârı Demir Heinrich ile bir araba geldi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-19',19,'Henry had placed iron bands around his heart because of his sorrow.','Heinrich üzüntüsünden kalbinin çevresine demir çemberler takmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('70e67693-3279-5f74-a92d-0c197068b4c9','cl-frog-prince-20',20,'As his master rode home free of the spell, the bands broke with joy.','Efendisi büyüden kurtulmuş olarak eve dönerken çemberler sevinçten kırıldı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','princess','princess','prenses','/ˌprɪnˈses/','She arrived in anger and placed a curse on the princess.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','golden','golden','altın; altından','/ˈɡəʊldən/','Every day, she lays a golden egg.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','well','well','kuyu','/wel/','A princess loved to play with her golden ball near a deep well.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','frog','frog','kurbağa','/frɒɡ/','A frog offered to bring it back if she would become his friend.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','plate','plate','tabak','/pleɪt/','He wanted to eat from her plate and sleep in her room.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','promise','promise','söz','/ˈprɑːmɪs/','The letter described a promise.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','dinner','dinner','akşam yemeği','/ˈdɪnə(r)/','A country mouse invites his town friend to dinner.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','rest','rest','dinlenme','/rest/','We need a short rest after the walk.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','frightened','frightened','korkmuş','/ˈfraɪtnd/','The frightened cat hides under the bed.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','witch','witch','cadı','/wɪtʃ/','The old woman is a witch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','loyal','loyal','sadık','/ˈlɔɪəl/','A carriage arrived with the prince''s loyal servant, Iron Henry.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','servant','servant','hizmetçi','/ˈsɜːvənt/','A carriage arrived with the prince''s loyal servant, Iron Henry.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','iron','iron','demir','/ˈaɪən/','A carriage arrived with the prince''s loyal servant, Iron Henry.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','free','free','özgür','/friː/','The lion is free again.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('70e67693-3279-5f74-a92d-0c197068b4c9','spell','spell','büyü','/spel/','As his master rode home free of the spell, the bands broke with joy.');
