insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','classic-rumpelstiltskin',1,'Rumpelstiltskin','Jacob and Wilhelm Grimm','A2','Gizem','Rumpelstiltskin. Samanı altına çeviren küçük adamın sakladığı isim. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','ee7d08f2-529a-51b3-a61d-6e8628b61536');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-01',1,'A miller boasted that his daughter could spin straw into gold.','Bir değirmenci, kızının samanı altına çevirebildiğiyle övündü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-02',2,'The king brought her to the palace and ordered her to prove it.','Kral kızı saraya getirip bunu kanıtlamasını emretti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-03',3,'She sat in a room full of straw and cried because she could not do it.','Kız saman dolu bir odada oturup bunu yapamadığı için ağladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-04',4,'A little man appeared and offered to help in exchange for her necklace.','Küçük bir adam belirdi ve kolyesi karşılığında yardım etmeyi teklif etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-05',5,'By morning, he had spun all the straw into gold.','Sabaha kadar bütün samanı altına çevirmişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-06',6,'The king demanded more gold, so she gave the little man her ring.','Kral daha çok altın istedi, kız da küçük adama yüzüğünü verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-07',7,'On the third night, she had nothing left to offer.','Üçüncü gece verecek hiçbir şeyi kalmamıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-08',8,'The little man asked for her first child if she became queen.','Küçük adam, kraliçe olursa doğacak ilk çocuğunu istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-09',9,'Without knowing what else to do, she agreed.','Başka ne yapacağını bilmeyen kız kabul etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-10',10,'The gold pleased the king, and he married her.','Altın kralı memnun etti ve kızla evlendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-11',11,'When their baby was born, the little man returned to collect his payment.','Bebekleri doğunca küçük adam karşılığını almaya geldi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-12',12,'The queen offered him her riches, but he wanted the child.','Kraliçe ona servetini teklif etti ama adam çocuğu istiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-13',13,'Seeing her tears, he gave her three days to guess his name.','Gözyaşlarını görünce adını tahmin etmesi için ona üç gün verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-14',14,'She sent messengers to search for unusual names everywhere.','Her yerde alışılmadık isimler aramaları için haberciler gönderdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-15',15,'For two days, every name she tried was wrong.','İki gün boyunca denediği bütün isimler yanlıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-16',16,'Then a messenger found a small house deep in the forest.','Sonra bir haberci ormanın derinliklerinde küçük bir ev buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-17',17,'A little man was dancing outside and singing that nobody knew his name was Rumpelstiltskin.','Küçük bir adam dışarıda dans ediyor ve adının Rumpelstiltskin olduğunu kimsenin bilmediğini söylüyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-18',18,'On the last day, the queen pretended to make two wrong guesses first.','Son gün kraliçe önce iki yanlış tahminde bulunuyormuş gibi yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-19',19,'Then she spoke his true name, and he became furious.','Sonra onun gerçek adını söyledi ve adam öfkeden deliye döndü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','cl-rumpelstiltskin-20',20,'He stamped so violently that he tore himself apart, and the queen kept her baby.','Öyle şiddetle yere vurdu ki kendini parçaladı ve bebek kraliçede kaldı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','miller','miller','değirmenci','/ˈmɪlə(r)/','A miller boasted that his daughter could spin straw into gold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','spin','spin','eğirmek','/spɪn/','A miller boasted that his daughter could spin straw into gold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','straw','straw','saman','/strɔː/','A miller boasted that his daughter could spin straw into gold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','gold','gold','altın','/ɡəʊld/','He wants all the gold at once.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','necklace','necklace','kolye','/ˈnekləs/','A little man appeared and offered to help in exchange for her necklace.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','ring','ring','yüzük','/rɪŋ/','The king demanded more gold, so she gave the little man her ring.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','nothing','nothing','hiçbir şey','/ˈnʌθɪŋ/','There is nothing in the box.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','queen','queen','kraliçe','/kwiːn/','A queen had a daughter with skin as white as snow and hair as black as ebony.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','married','married','evlendi','/ˈmærid/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','tears','tears','gözyaşları','/tɪəz/','Her tears fell into his eyes, and he could see once more.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','messengers','messengers','haberciler','/ˈmesɪndʒəz/','She sent messengers to search for unusual names everywhere.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','forest','forest','orman','/ˈfɔːrɪst/','The forest was full of birds.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('d6eab5e2-369f-5284-a532-d4bfcee0d0da','nobody','nobody','hiç kimse','/ˈnoʊbədi/','Nobody is at home today.');
