insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('250414d4-faff-5f5c-ac89-f9625e530d29','classic-golden-goose',1,'The Golden Goose','Jacob and Wilhelm Grimm','A2','Macera','Altın Kaz. Paylaşmayı bilen küçük kardeşin peşine takılan tuhaf bir kalabalık. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','2a5cfa24-38a2-566a-a7d9-a308f219e441');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-01',1,'Three brothers went into the forest to cut wood, one after another.','Üç kardeş sırayla odun kesmek için ormana gitti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-02',2,'The two older brothers refused to share their food with a little grey man.','İki büyük kardeş yiyeceklerini küçük, gri saçlı bir adamla paylaşmayı reddetti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-03',3,'Both hurt themselves and had to return home.','İkisi de yaralanıp eve dönmek zorunda kaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-04',4,'The youngest brother was called Simpleton, but he willingly shared his poor meal.','En küçük kardeşe Aptalcık deniyordu ama basit yemeğini seve seve paylaştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-05',5,'The little man showed him a tree and told him to cut it down.','Küçük adam ona bir ağaç gösterip kesmesini söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-06',6,'Under its roots, he found a goose with golden feathers.','Köklerinin altında altın tüylü bir kaz buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-07',7,'He took the goose to an inn, where three sisters wanted to steal its feathers.','Kazı bir hana götürdü; orada üç kız kardeş kazın tüylerini çalmak istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-08',8,'When the first sister touched it, her hand stuck fast.','İlk kız kardeş kaza dokunduğunda eli yapışıp kaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-09',9,'The others touched her and became stuck, too.','Ötekiler ona dokununca onlar da yapışıp kaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-10',10,'The next morning, the young man walked away with the goose and the sisters behind him.','Ertesi sabah genç adam kazla yola çıktı, kız kardeşler de arkasından geldi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-11',11,'A parson, a clerk, and two farmers tried to help but joined the strange line.','Bir papaz, bir görevli ve iki çiftçi yardım etmeye çalıştı ama tuhaf sıraya katıldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-12',12,'In a nearby city, a princess had never laughed.','Yakındaki bir şehirde bir prenses hiç gülmemişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-13',13,'The king had promised her hand to whoever could make her laugh.','Kral onu güldürebilen kişiyle evlendireceğine söz vermişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-14',14,'When she saw the goose and its followers, she laughed loudly.','Prenses kazı ve peşindekileri görünce kahkahalarla güldü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-15',15,'But the king did not want such a simple young man for his daughter.','Ama kral kızı için böylesine saf bir genç adamı istemiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-16',16,'He demanded impossible amounts of food and drink, and a ship that could travel on land and water.','Yenmesi ve içilmesi imkânsız miktarlarda yiyecek ve içecek tüketilmesini, bir de karada ve suda gidebilen bir gemi istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-17',17,'The little grey man helped the youngest brother complete every task.','Küçük, gri saçlı adam en küçük kardeşin her görevi tamamlamasına yardım etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-18',18,'The king could no longer refuse to keep his promise.','Kral artık sözünü tutmayı reddedemedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-19',19,'The young man married the princess and later became king.','Genç adam prensesle evlenip daha sonra kral oldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('250414d4-faff-5f5c-ac89-f9625e530d29','cl-golden-goose-20',20,'His kindness had brought him help when he needed it most.','İyiliği, en çok ihtiyaç duyduğu anda ona yardım getirmişti.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','brothers','brothers','erkek kardeşler','/ˈbrʌðəz/','Three brothers went into the forest to cut wood, one after another.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','forest','forest','orman','/ˈfɔːrɪst/','The forest was full of birds.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','share','share','paylaşmak','/ʃer/','They share the cake.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','food','food','yiyecek','/fuːd/','He offers simple food from the fields.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','return','return','dönmek','/rɪˈtɜːrn/','They promised to return.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','meal','meal','öğün','/miːl/','The town mouse is not happy with the meal.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','goose','goose','kaz','/ɡuːs/','Under its roots, he found a goose with golden feathers.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','golden','golden','altın; altından','/ˈɡəʊldən/','Every day, she lays a golden egg.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','feathers','feathers','tüyler','/ˈfeðəz/','"What beautiful feathers you have!" he says.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','inn','inn','han','/ɪn/','He took the goose to an inn, where three sisters wanted to steal its feathers.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','parson','parson','papaz','/ˈpɑːsn/','A parson, a clerk, and two farmers tried to help but joined the strange line.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','princess','princess','prenses','/ˌprɪnˈses/','She arrived in anger and placed a curse on the princess.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','promise','promise','söz','/ˈprɑːmɪs/','The letter described a promise.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('250414d4-faff-5f5c-ac89-f9625e530d29','married','married','evlendi','/ˈmærid/','After the queen died, the king married another woman.');
