insert into public.stories(id) values('classic-elves-shoemaker') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('4e7cf420-c00f-5475-aab0-2ddd00378743','classic-elves-shoemaker',1,'The Elves and the Shoemaker','Jacob and Wilhelm Grimm','A2','Günlük yaşam','Ayakkabıcı ve Cinler. Yoksul bir ayakkabıcı, gizli yardımcılarına teşekkür etmenin yolunu bulur. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','a7726b28-f8ae-581c-a4ed-f763f4ecaa52');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-01',1,'A shoemaker had become so poor that he had leather for only one pair of shoes.','Bir ayakkabıcı o kadar yoksullaşmıştı ki yalnızca bir çift ayakkabılık derisi kalmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-02',2,'He cut out the leather in the evening and left it on his workbench.','Akşam deriyi kesip tezgâhının üzerinde bıraktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-03',3,'When he returned in the morning, the shoes were already finished.','Sabah döndüğünde ayakkabılar çoktan bitmişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-04',4,'Their fine stitching amazed him.','Güzel dikişleri onu hayrete düşürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-05',5,'A customer paid enough for him to buy leather for two more pairs.','Bir müşteri, iki çift daha ayakkabı yapacak deri almasına yetecek kadar para ödedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-06',6,'Again, he cut the leather and found perfect shoes waiting the next morning.','Ayakkabıcı yine deriyi kesti ve ertesi sabah kusursuz ayakkabıların kendisini beklediğini gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-07',7,'Night after night, the same thing happened.','Her gece aynı şey oldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-08',8,'Soon the shoemaker could live comfortably again.','Çok geçmeden ayakkabıcı yeniden rahat yaşayabilir hâle geldi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-09',9,'Before Christmas, he and his wife decided to discover their secret helpers.','Noel''den önce karısıyla gizli yardımcılarını bulmaya karar verdiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-10',10,'They hid in the workshop and watched the table.','Atölyede saklanıp masayı izlediler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-11',11,'At midnight, two little elves without clothes appeared.','Gece yarısı üzerinde giysi olmayan iki küçük cin belirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-12',12,'They worked quickly and carefully until every shoe was ready.','Bütün ayakkabılar hazır olana kadar hızlı ve dikkatli çalıştılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-13',13,'Then they disappeared before dawn.','Sonra şafaktan önce ortadan kayboldular.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-14',14,'The couple wanted to thank them for their kindness.','Çift, iyilikleri için onlara teşekkür etmek istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-15',15,'The wife made tiny shirts, coats, and trousers.','Kadın küçücük gömlekler, ceketler ve pantolonlar dikti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-16',16,'The shoemaker made two pairs of little shoes.','Ayakkabıcı da iki çift küçük ayakkabı yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-17',17,'They left these gifts on the table instead of leather.','Masaya deri yerine bu hediyeleri bıraktılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-18',18,'The elves put on the clothes, danced with delight, and left.','Cinler giysileri giydi, sevinçle dans etti ve gitti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-19',19,'They never returned to the workshop.','Atölyeye bir daha dönmediler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4e7cf420-c00f-5475-aab0-2ddd00378743','cl-elves-shoemaker-20',20,'But the shoemaker''s work continued to prosper, and he remembered their help.','Ama ayakkabıcının işleri iyi gitmeye devam etti ve onların yardımını unutmadı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4e7cf420-c00f-5475-aab0-2ddd00378743','shoemaker','shoemaker','ayakkabıcı','/ˈʃuːmeɪkə(r)/','A shoemaker had become so poor that he had leather for only one pair of shoes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4e7cf420-c00f-5475-aab0-2ddd00378743','leather','leather','deri','/ˈleðə(r)/','A shoemaker had become so poor that he had leather for only one pair of shoes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4e7cf420-c00f-5475-aab0-2ddd00378743','workbench','workbench','iş tezgâhı','/ˈwɜːkbentʃ/','He cut out the leather in the evening and left it on his workbench.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4e7cf420-c00f-5475-aab0-2ddd00378743','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4e7cf420-c00f-5475-aab0-2ddd00378743','stitching','stitching','dikiş','/ˈstɪtʃɪŋ/','Their fine stitching amazed him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4e7cf420-c00f-5475-aab0-2ddd00378743','discover','discover','keşfetmek','/dɪˈskʌvər/','They hoped to discover a new place.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4e7cf420-c00f-5475-aab0-2ddd00378743','elves','elves','cinler','/elvz/','At midnight, two little elves without clothes appeared.');
