insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','classic-tom-thumb',1,'Tom Thumb','Jacob and Wilhelm Grimm','A2','Macera','Parmak Çocuk. Parmak kadar küçük bir çocuğun büyük dünyadaki yolculuğu. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','e5de9cc6-e52f-5639-a796-d3982c8cbdf0');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-01',1,'A poor couple wished for a child, even one no bigger than a thumb.','Yoksul bir çift, parmak kadar küçük bile olsa bir çocuk istiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-02',2,'Their wish came true, and they named their tiny son Tom Thumb.','Dilekleri gerçekleşti ve minicik oğullarına Parmak Çocuk adını verdiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-03',3,'Though he never grew taller, he was clever and full of energy.','Boyu hiç uzamasa da akıllı ve enerji doluydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-04',4,'One day, he guided his father''s horse while sitting inside its ear.','Bir gün atın kulağının içinde oturarak babasının atını yönlendirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-05',5,'Two strangers saw the moving cart and wanted to buy the little boy.','İki yabancı hareket eden arabayı gördü ve küçük çocuğu satın almak istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-06',6,'Tom told his father to accept because he knew how to escape.','Parmak Çocuk kaçmayı bildiği için babasına teklifi kabul etmesini söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-07',7,'On the road, he hid in a mouse hole and waited until the strangers left.','Yolda bir fare deliğine saklanıp yabancılar gidene kadar bekledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-08',8,'That night, he met two thieves planning to rob a parson.','O gece bir papazı soymayı planlayan iki hırsızla karşılaştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-09',9,'They asked him to squeeze through the bars and help them.','Ondan parmaklıkların arasından geçip kendilerine yardım etmesini istediler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-10',10,'Instead, he shouted so loudly that a servant woke up and the thieves ran away.','O ise öyle yüksek sesle bağırdı ki bir hizmetçi uyandı ve hırsızlar kaçtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-11',11,'Tom fell asleep in some hay.','Parmak Çocuk bir yığın otun içinde uyuyakaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-12',12,'In the morning, the hay was carried to a cow, which swallowed him.','Sabah ot bir ineğe götürüldü ve inek çocuğu yuttu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-13',13,'From the cow''s stomach, he called for less hay.','İneğin midesinden daha az ot verilmesini istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-14',14,'The frightened parson ordered the talking cow to be killed.','Korkan papaz, konuşan ineğin öldürülmesini emretti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-15',15,'Its stomach was thrown away, and a hungry wolf ate it with Tom inside.','Midesi atıldı ve aç bir kurt, içinde Parmak Çocuk varken onu yedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-16',16,'Tom persuaded the wolf to enter his parents'' house for a great meal.','Parmak Çocuk kurdu büyük bir yemek için ailesinin evine girmeye ikna etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-17',17,'After eating too much, the wolf could no longer squeeze out.','Kurt çok fazla yiyince artık dar delikten çıkamadı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-18',18,'Tom shouted, and his father recognized his voice.','Parmak Çocuk bağırdı ve babası sesini tanıdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-19',19,'The parents killed the wolf and carefully freed their son.','Anne babası kurdu öldürüp oğullarını dikkatle kurtardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cl-tom-thumb-20',20,'Safe at home, Tom said he had seen enough of the world for a while.','Evinde güvende olan Parmak Çocuk, bir süreliğine dünyayı yeterince gördüğünü söyledi.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','bigger','bigger','daha büyük','/ˈbɪɡər/','My room is bigger than yours.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','thumb','thumb','başparmak','/θʌm/','A poor couple wished for a child, even one no bigger than a thumb.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','clever','clever','akıllı','/ˈklevə(r)/','A clever idea can solve a difficult problem.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','strangers','strangers','yabancılar','/ˈstreɪndʒəz/','They warned her not to open the door to strangers.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cart','cart','at arabası','/kɑːt/','Two strangers saw the moving cart and wanted to buy the little boy.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','boy','boy','erkek çocuk, oğlan','/bɔɪ/','The boy plays in the park.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','father','father','baba','/ˈfɑːðə(r)/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','road','road','yol','/roʊd/','The road goes to the village.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','mouse','mouse','fare','/maʊs/','The mouse is very small.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','hole','hole','delik','/həʊl/','The mice run and hide in a hole.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','thieves','thieves','hırsızlar','/θiːvz/','That night, he met two thieves planning to rob a parson.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','parson','parson','papaz','/ˈpɑːsn/','A parson, a clerk, and two farmers tried to help but joined the strange line.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','servant','servant','hizmetçi','/ˈsɜːvənt/','A carriage arrived with the prince''s loyal servant, Iron Henry.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','hay','hay','kuru ot','/heɪ/','A dog lies in a manger full of hay.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','cow','cow','inek','/kaʊ/','In the morning, the hay was carried to a cow, which swallowed him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','frightened','frightened','korkmuş','/ˈfraɪtnd/','The frightened cat hides under the bed.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','hungry','hungry','aç','/ˈhʌŋɡri/','I am hungry after school.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','wolf','wolf','kurt','/wʊlf/','The wolf runs to the house.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','meal','meal','öğün','/miːl/','The town mouse is not happy with the meal.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','much','much','çok','/mʌtʃ/','Thank you very much.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','voice','voice','ses','/vɔɪs/','"You must have a beautiful voice, too."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('83d8e1d1-155d-5dd4-a8ee-00baea5885cd','safe','safe','güvenli','/seɪf/','"I prefer a simple meal and a safe home."');
