insert into public.stories(id) values('classic-wolf-seven-kids') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','classic-wolf-seven-kids',1,'The Wolf and the Seven Young Goats','Jacob and Wilhelm Grimm','A2','Macera','Kurt ve Yedi Oğlak. Annesinin uyarısını unutan oğlaklar ile kurnaz bir kurt. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','77c57ec2-a892-5e73-a290-5794f830fadb');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-01',1,'A mother goat left her seven children at home while she looked for food.','Bir anne keçi yiyecek ararken yedi yavrusunu evde bıraktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-02',2,'She warned them not to open the door to the wolf.','Kurda kapıyı açmamaları için onları uyardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-03',3,'They could recognize him by his rough voice and black paws.','Onu kalın sesinden ve siyah patilerinden tanıyabilirlerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-04',4,'Soon the wolf knocked and pretended to be their mother.','Çok geçmeden kurt kapıyı çaldı ve anneleriymiş gibi davrandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-05',5,'The young goats heard his rough voice and refused to open.','Oğlaklar onun kalın sesini duyup kapıyı açmayı reddetti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-06',6,'The wolf ate chalk to soften his voice and tried again.','Kurt sesini yumuşatmak için tebeşir yiyip yeniden denedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-07',7,'But this time, the children noticed his black paw at the window.','Ama çocuklar bu kez penceredeki siyah patisini fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-08',8,'He covered his paw with dough and white flour.','Patisini hamur ve beyaz unla kapladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-09',9,'When he knocked a third time, the goats believed him and opened the door.','Üçüncü kez kapıyı çaldığında oğlaklar ona inanıp kapıyı açtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-10',10,'The frightened children hid around the house.','Korkan yavrular evin çeşitli yerlerine saklandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-11',11,'The wolf found and swallowed six of them.','Kurt altısını bulup yuttu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-12',12,'Only the youngest escaped by hiding inside the clock.','Yalnızca en küçükleri saatin içine saklanarak kurtuldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-13',13,'Their mother returned and found the house in a terrible mess.','Anneleri dönüp evi korkunç bir dağınıklık içinde buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-14',14,'The youngest came out and told her everything.','En küçük yavru dışarı çıkıp ona her şeyi anlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-15',15,'They found the wolf asleep under a tree, with something moving in his belly.','Kurdu bir ağacın altında uyurken buldular; karnında bir şeyler hareket ediyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-16',16,'The mother cut his belly open, and the six young goats came out alive.','Anne karnını açtı ve altı oğlak sağ olarak dışarı çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-17',17,'They filled the empty space with stones, and she sewed it shut.','Boş yeri taşlarla doldurdular, anne de dikerek kapattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-18',18,'When the wolf woke, he went to a well to drink.','Kurt uyandığında su içmek için bir kuyuya gitti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-19',19,'The heavy stones pulled him into the water, and he drowned.','Ağır taşlar onu suya çekti ve kurt boğuldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','cl-wolf-seven-kids-20',20,'The mother and her seven children celebrated being together again.','Anne ile yedi yavrusu yeniden bir arada olmalarını kutladı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','food','food','yiyecek','/fuːd/','He offers simple food from the fields.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','wolf','wolf','kurt','/wʊlf/','The wolf runs to the house.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','voice','voice','ses','/vɔɪs/','"You must have a beautiful voice, too."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','goats','goats','keçiler','/ɡəʊts/','The young goats heard his rough voice and refused to open.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','chalk','chalk','tebeşir','/tʃɔːk/','The wolf ate chalk to soften his voice and tried again.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','paw','paw','pençe','/pɔː/','The lion opens his paw.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','window','window','pencere','/ˈwɪndoʊ/','Anna looks out of her window.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','flour','flour','un','/ˈflaʊə(r)/','He covered his paw with dough and white flour.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','frightened','frightened','korkmuş','/ˈfraɪtnd/','The frightened cat hides under the bed.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','belly','belly','karın','/ˈbeli/','The wolf has a full belly.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','well','well','kuyu','/wel/','A princess loved to play with her golden ball near a deep well.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('227e553c-63f2-503f-add8-1fdc0d9d86a1','heavy','heavy','ağır','/ˈhevi/','His bag is heavy.');
