insert into public.stories(id) values('classic-twelve-dancing-princesses') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('7eac003e-201f-56a6-ae8a-c50420a42e37','classic-twelve-dancing-princesses',1,'The Twelve Dancing Princesses','Jacob and Wilhelm Grimm','A2','Gizem','Dans Eden On İki Prenses. Her sabah eskiyen ayakkabıların ardındaki gizli geçit. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Arthur Rackham; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','343b1280-cedd-56a2-a022-9ce4d64bd38f');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-01',1,'A king had twelve daughters who slept in one locked room.','Bir kralın, kilitli bir odada uyuyan on iki kızı vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-02',2,'Every morning, their shoes were worn out as if they had danced all night.','Her sabah ayakkabıları, bütün gece dans etmişler gibi eskimiş oluyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-03',3,'The king promised a great reward to anyone who could discover their secret.','Kral, sırlarını ortaya çıkaran kişiye büyük bir ödül vereceğine söz verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-04',4,'Many princes tried, but each fell asleep and learned nothing.','Birçok prens denedi ama hepsi uyuyakaldı ve hiçbir şey öğrenemedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-05',5,'An old soldier met a woman who gave him useful advice and an invisible cloak.','Yaşlı bir asker, kendisine yararlı bir öğüt ve görünmezlik pelerini veren bir kadınla karşılaştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-06',6,'She told him not to drink the wine offered by the princesses.','Kadın ona prenseslerin sunduğu şarabı içmemesini söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-07',7,'At the palace, he secretly poured away the wine and pretended to sleep.','Sarayda şarabı gizlice döküp uyuyormuş gibi yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-08',8,'The eldest princess opened a hidden door beneath her bed.','En büyük prenses yatağının altındaki gizli bir kapıyı açtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-09',9,'Wearing the cloak, the soldier followed them down the stairs.','Asker pelerini giyip merdivenlerden aşağı onları izledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-10',10,'They passed through woods with silver, gold, and diamond leaves.','Gümüş, altın ve elmas yapraklı korulardan geçtiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-11',11,'He broke off a branch from each wood to keep as proof.','Kanıt olarak saklamak için her korudan bir dal kopardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-12',12,'At a lake, twelve princes waited with twelve boats.','Bir gölde on iki prens, on iki kayıkla bekliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-13',13,'The soldier stepped into the youngest princess''s boat without being seen.','Asker görünmeden en küçük prensesin kayığına bindi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-14',14,'Across the water, a brightly lit castle waited for the dancers.','Suyun karşısında, ışıl ışıl bir şato dansçıları bekliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-15',15,'The princesses danced until their shoes were worn through.','Prensesler ayakkabıları delinene kadar dans etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-16',16,'The soldier took a cup and followed them home before morning.','Asker bir kadeh aldı ve sabah olmadan onları eve kadar izledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-17',17,'He watched them for two more nights to be certain.','Emin olmak için onları iki gece daha izledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-18',18,'Then he showed the king the branches and cup, and described the secret journey.','Sonra krala dalları ve kadehi gösterip gizli yolculuğu anlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-19',19,'The princesses could no longer deny what they had done.','Prensesler artık yaptıklarını inkâr edemedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('7eac003e-201f-56a6-ae8a-c50420a42e37','cl-twelve-dancing-princesses-20',20,'The soldier chose to marry the eldest princess and was promised the kingdom.','Asker en büyük prensesle evlenmeyi seçti ve krallık ona vaat edildi.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('7eac003e-201f-56a6-ae8a-c50420a42e37','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
