insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('7eac003e-201f-56a6-ae8a-c50420a42e37','invisible','invisible','görünmez','/ɪnˈvɪzəbl/','An old soldier met a woman who gave him useful advice and an invisible cloak.');
