insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('7eac003e-201f-56a6-ae8a-c50420a42e37','princesses','princesses','prensesler','/ˌprɪnˈsesɪz/','She told him not to drink the wine offered by the princesses.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('7eac003e-201f-56a6-ae8a-c50420a42e37','princess','princess','prenses','/ˌprɪnˈses/','She arrived in anger and placed a curse on the princess.');
