insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('7eac003e-201f-56a6-ae8a-c50420a42e37','proof','proof','kanıt','/pruːf/','He broke off a branch from each wood to keep as proof.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('7eac003e-201f-56a6-ae8a-c50420a42e37','boat','boat','tekne','/boʊt/','A little boat floated away.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('7eac003e-201f-56a6-ae8a-c50420a42e37','castle','castle','şato','/ˈkɑːsl/','Everyone in the castle fell asleep with her.');
