insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('bca12041-3bc4-537f-adb1-579f322db346','classic-brave-little-tailor',1,'The Brave Little Tailor','Jacob and Wilhelm Grimm','A2','Macera','Cesur Terzi. Yedi sineği bir vuruşta öldüren terzinin zekâyla kazandığı ün. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','5674205c-95ef-584a-a0b2-8bcd456f0b03');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-01',1,'A tailor was eating bread and jam when flies crowded around his meal.','Bir terzi ekmek ve reçel yerken sinekler yemeğinin çevresine toplandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-02',2,'He struck with a cloth and killed seven flies at once.','Bir bezle vurup yedi sineği birden öldürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-03',3,'Proud of himself, he made a belt that said, "Seven at one blow."','Kendisiyle gururlanıp üzerine "Bir vuruşta yedi" yazdığı bir kemer yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-04',4,'Then he set off to see the world, carrying cheese and a bird.','Sonra yanına peynir ve bir kuş alıp dünyayı görmeye çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-05',5,'A giant read his belt and thought he had killed seven men.','Bir dev kemerini okuyup yedi adam öldürdüğünü sandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-06',6,'When the giant squeezed water from a stone, the tailor squeezed his cheese.','Dev bir taştan su sıkınca terzi de peynirini sıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-07',7,'When the giant threw a stone high, the tailor let his bird fly away.','Dev bir taşı yukarı fırlatınca terzi kuşunu uçurdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-08',8,'He also tricked the giant into carrying a whole tree alone.','Ayrıca devi kandırıp koca bir ağacı tek başına taşıttı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-09',9,'News of the tailor''s supposed strength reached a king.','Terzinin sözde gücünün haberi bir krala ulaştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-10',10,'The king promised him land and a princess if he defeated two dangerous giants.','Kral, iki tehlikeli devi yenerse ona toprak ve bir prenses vereceğine söz verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-11',11,'The tailor found the giants asleep beneath a tree.','Terzi devleri bir ağacın altında uyurken buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-12',12,'He climbed above them and dropped stones on each in turn.','Tepelerine tırmanıp sırayla her birinin üzerine taş attı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-13',13,'Each giant blamed the other, and they fought until both were dead.','Her dev diğerini suçladı ve ikisi de ölene kadar dövüştüler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-14',14,'The king then demanded that he capture a unicorn.','Kral sonra ondan bir tek boynuzlu at yakalamasını istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-15',15,'The tailor jumped behind a tree, and the charging animal''s horn stuck in the trunk.','Terzi bir ağacın arkasına atladı ve üzerine koşan hayvanın boynuzu gövdeye saplandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-16',16,'Next, he trapped a wild boar inside a chapel.','Ardından yabani bir domuzu bir şapelin içine hapsetti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-17',17,'With every task complete, the tailor married the princess.','Bütün görevleri tamamlayan terzi prensesle evlendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-18',18,'One night, she heard him talking in his sleep about his old trade.','Bir gece karısı onun uykusunda eski mesleğinden söz ettiğini duydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-19',19,'When servants came to take him away, he pretended to sleep and boasted about his victories.','Hizmetçiler onu götürmeye geldiğinde uyuyormuş gibi yapıp zaferleriyle övündü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bca12041-3bc4-537f-adb1-579f322db346','cl-brave-little-tailor-20',20,'They fled in fear, and the clever tailor remained in the palace.','Korkuyla kaçtılar ve akıllı terzi sarayda kaldı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','tailor','tailor','terzi','/ˈteɪlə(r)/','A tailor was eating bread and jam when flies crowded around his meal.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','meal','meal','öğün','/miːl/','The town mouse is not happy with the meal.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','cloth','cloth','kumaş','/klɒθ/','He struck with a cloth and killed seven flies at once.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','proud','proud','gururlu','/praʊd/','The crow feels proud.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','belt','belt','kemer','/belt/','Proud of himself, he made a belt that said, "Seven at one blow."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','giant','giant','dev','/ˈdʒaɪənt/','The giant owns a garden.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','high','high','yüksek','/haɪ/','The bird sits on a high wall.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','alone','alone','yalnız','/əˈloʊn/','He walks home alone.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','princess','princess','prenses','/ˌprɪnˈses/','She arrived in anger and placed a curse on the princess.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','unicorn','unicorn','tek boynuzlu at','/ˈjuːnɪkɔːn/','The king then demanded that he capture a unicorn.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','boar','boar','yaban domuzu','/bɔː(r)/','Next, he trapped a wild boar inside a chapel.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','chapel','chapel','şapel','/ˈtʃæpl/','Next, he trapped a wild boar inside a chapel.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('bca12041-3bc4-537f-adb1-579f322db346','married','married','evlendi','/ˈmærid/','After the queen died, the king married another woman.');
