insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('475180b3-60df-557e-a169-e971347843ae','classic-goose-girl',1,'The Goose Girl','Jacob and Wilhelm Grimm','A2','Gizem','Kaz Çobanı Kız. Gerçek kimliğini kaybeden bir prensesin sırrını ortaya çıkaran rüzgâr. A2 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Walter Crane; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','2413a828-c36a-52be-ab3e-c0d8bd07ca50');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-01',1,'A queen sent her daughter to marry a prince in a distant kingdom.','Bir kraliçe kızını, uzak bir krallıktaki bir prensle evlenmesi için gönderdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-02',2,'The princess travelled with a servant and her talking horse, Falada.','Prenses, bir hizmetçi ve konuşan atı Falada ile yolculuk yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-03',3,'Her mother gave her a cloth with three drops of blood to protect her.','Annesi onu koruması için üç damla kan taşıyan bir bez verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-04',4,'On the journey, the servant refused to bring her water.','Yolculukta hizmetçi ona su getirmeyi reddetti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-05',5,'As the princess bent down to drink, she lost the cloth in a stream.','Prenses su içmek için eğildiğinde bezi bir derede kaybetti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-06',6,'The servant forced her to exchange clothes and promise not to reveal the truth.','Hizmetçi onu kıyafetlerini değiştirmeye ve gerçeği açıklamamaya söz vermeye zorladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-07',7,'At the palace, the servant claimed to be the bride.','Sarayda hizmetçi gelinin kendisi olduğunu ileri sürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-08',8,'The real princess was sent to help a boy named Conrad look after geese.','Gerçek prenses, Conrad adındaki bir çocuğa kazlara bakarken yardım etmeye gönderildi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-09',9,'Afraid that Falada would speak, the false bride had the horse killed.','Falada''nın konuşmasından korkan sahte gelin atı öldürttü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-10',10,'The princess paid to have his head hung above the gate she passed each day.','Prenses, atın başının her gün geçtiği kapının üstüne asılması için para verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-11',11,'The head still spoke to her and sorrowfully remembered her mother.','Atın başı onunla hâlâ konuşuyor ve annesini üzüntüyle anıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-12',12,'In the fields, Conrad tried to take a strand of her golden hair.','Tarlalarda Conrad onun altın saçlarından bir tutam almaya çalıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-13',13,'She called on the wind, which blew his hat away until she had finished combing her hair.','Kız rüzgâra seslendi; rüzgâr da saçını taramayı bitirene kadar çocuğun şapkasını uçurdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-14',14,'Conrad complained to the old king, who secretly watched them the next day.','Conrad yaşlı krala şikâyet etti, kral da ertesi gün onları gizlice izledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-15',15,'The girl could not tell the king her story because of her promise.','Kız verdiği söz yüzünden krala hikâyesini anlatamadı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-16',16,'He suggested telling it to an iron stove instead, and listened from outside.','Kral ona bunun yerine bir demir sobaya anlatmasını önerdi ve dışarıdan dinledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-17',17,'After learning the truth, he dressed her as a princess and brought her to dinner.','Gerçeği öğrenince onu prenses gibi giydirip yemeğe getirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-18',18,'The false bride failed to recognize her and suggested a harsh punishment for such a deceitful servant.','Sahte gelin onu tanımadı ve böyle yalancı bir hizmetçi için ağır bir ceza önerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-19',19,'The king revealed that she had named her own punishment.','Kral onun kendi cezasını söylediğini açıkladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('475180b3-60df-557e-a169-e971347843ae','cl-goose-girl-20',20,'The real princess married the prince, and her stolen identity was restored.','Gerçek prenses prensle evlendi ve çalınan kimliğine yeniden kavuştu.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','queen','queen','kraliçe','/kwiːn/','A queen had a daughter with skin as white as snow and hair as black as ebony.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','princess','princess','prenses','/ˌprɪnˈses/','She arrived in anger and placed a curse on the princess.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','servant','servant','hizmetçi','/ˈsɜːvənt/','A carriage arrived with the prince''s loyal servant, Iron Henry.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','cloth','cloth','kumaş','/klɒθ/','He struck with a cloth and killed seven flies at once.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','journey','journey','yolculuk','/ˈdʒɜːrni/','Every journey starts somewhere.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','promise','promise','söz','/ˈprɑːmɪs/','The letter described a promise.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','truth','truth','gerçek','/truːθ/','A liar can lose people''s trust, even when he tells the truth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','bride','bride','gelin','/braɪd/','The prince hopes to find a bride.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','boy','boy','erkek çocuk, oğlan','/bɔɪ/','The boy plays in the park.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','geese','geese','kazlar','/ɡiːs/','The real princess was sent to help a boy named Conrad look after geese.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','gate','gate','bahçe kapısı','/ɡeɪt/','They met beside the gate.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','golden','golden','altın; altından','/ˈɡəʊldən/','Every day, she lays a golden egg.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','wind','wind','rüzgâr','/wɪnd/','The wind carried the boat.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','iron','iron','demir','/ˈaɪən/','A carriage arrived with the prince''s loyal servant, Iron Henry.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','stove','stove','soba','/stəʊv/','He suggested telling it to an iron stove instead, and listened from outside.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','dinner','dinner','akşam yemeği','/ˈdɪnə(r)/','A country mouse invites his town friend to dinner.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','own','own','kendi','/oʊn/','She has her own room.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','married','married','evlendi','/ˈmærid/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('475180b3-60df-557e-a169-e971347843ae','identity','identity','kimlik','/aɪˈdentəti/','The real princess married the prince, and her stolen identity was restored.');
