insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','classic-ugly-duckling',1,'The Ugly Duckling','Hans Christian Andersen','B1','Macera','Çirkin Ördek Yavrusu. Kendini ait olmadığı bir yerde bulan yavrunun, kim olduğunu keşfetmesi. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Vilhelm Pedersen; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','d986da99-d272-57b3-afd1-2123ef04194f');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-01',1,'A duck sat on her nest, waiting for the last and largest egg to hatch.','Bir ördek yuvasında oturmuş, son ve en büyük yumurtanın çatlamasını bekliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-02',2,'When it opened, a large grey bird stepped out among her little ducklings.','Yumurta açıldığında küçük ördek yavrularının arasına iri, gri bir kuş çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-03',3,'He looked different from the others, but he could swim very well.','Diğerlerinden farklı görünüyordu ama çok iyi yüzebiliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-04',4,'His mother took all her young to the farmyard and tried to protect him.','Annesi bütün yavrularını çiftliğin avlusuna götürdü ve onu korumaya çalıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-05',5,'The other animals mocked him, and even his brothers and sisters treated him cruelly.','Diğer hayvanlar onunla alay ediyor, kardeşleri bile ona zalimce davranıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-06',6,'At last, he fled through the hedge, believing that nobody could ever like him.','Sonunda kimsenin kendisini sevemeyeceğine inanarak çitin arasından kaçtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-07',7,'He found wild ducks in a marsh, but he could not stay there in peace.','Bir bataklıkta yaban ördekleri buldu ama orada huzur içinde kalamadı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-08',8,'Hunters arrived, and frightened birds rose into the air.','Avcılar geldi ve korkan kuşlar havalandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-09',9,'The lonely bird escaped and eventually reached a poor woman''s cottage.','Yalnız kuş kaçtı ve sonunda yoksul bir kadının kulübesine ulaştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-10',10,'She kept a cat and a hen, who thought their own abilities were the only ones that mattered.','Kadının bir kedisi ve bir tavuğu vardı; onlar yalnızca kendi yeteneklerinin önemli olduğunu düşünüyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-11',11,'The bird could neither lay eggs nor purr, and he missed swimming.','Kuş ne yumurtlayabiliyor ne de mırıldanabiliyordu; yüzmeyi de özlüyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-12',12,'Unable to explain his feelings, he left the cottage and returned to the open water.','Duygularını anlatamayınca kulübeyi bırakıp açık suya döndü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-13',13,'Autumn came, and he saw a flock of beautiful white swans flying overhead.','Sonbahar geldi ve tepesinden geçen güzel beyaz kuğulardan oluşan bir sürü gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-14',14,'Their long necks and powerful wings filled him with a feeling he did not understand.','Uzun boyunları ve güçlü kanatları, içini anlamadığı bir duyguyla doldurdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-15',15,'He loved them without knowing why, although he did not dare to join them.','Aralarına katılmaya cesaret edemese de nedenini bilmeden onları sevdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-16',16,'Winter grew bitterly cold, and he swam to keep a small patch of water from freezing.','Kış çok soğudu; küçük bir su parçasının donmasını önlemek için yüzdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-17',17,'One night, he became exhausted and was trapped in the ice.','Bir gece bitkin düşerek buzun içinde mahsur kaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-18',18,'A farmer broke the ice and carried him home.','Bir çiftçi buzu kırıp onu evine taşıdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-19',19,'The children wanted to play, but the frightened bird thought they would hurt him.','Çocuklar oynamak istedi ama korkmuş kuş onların kendisine zarar vereceğini sandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-20',20,'After causing confusion in the kitchen, he escaped outside again.','Mutfakta karışıklık çıkardıktan sonra yeniden dışarı kaçtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-21',21,'At last, spring returned, and he discovered that his wings had grown strong.','Sonunda bahar geri döndü ve kuş kanatlarının güçlendiğini fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-22',22,'He flew into a garden where three white swans moved across the water.','Üç beyaz kuğunun suyun üzerinde süzüldüğü bir bahçeye uçtu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-23',23,'He approached them, expecting rejection even from these beautiful birds.','Bu güzel kuşların bile kendisini reddedeceğini düşünerek onlara yaklaştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-24',24,'But they welcomed him, and when he lowered his head, he saw his reflection.','Ama onu sevinçle karşıladılar; başını eğdiğinde sudaki yansımasını gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-25',25,'He was no longer a grey, awkward youngster but a graceful white swan.','Artık gri ve sakar bir yavru değil, zarif beyaz bir kuğuydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-26',26,'Children came to feed the swans and admired the beautiful newcomer.','Çocuklar kuğuları beslemeye geldi ve güzel yeni kuşa hayran kaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-27',27,'He remembered his suffering, but happiness had not made him proud or unkind.','Çektiği acıları hatırlıyordu ama mutluluk onu kibirli ya da kötü biri yapmamıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','cl-ugly-duckling-28',28,'He had never dreamed that he could belong so completely.','Bir yere böylesine ait olabileceğini hiç hayal etmemişti.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','duck','duck','ördek','/dʌk/','A duck sat on her nest, waiting for the last and largest egg to hatch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','nest','nest','yuva','/nest/','A duck sat on her nest, waiting for the last and largest egg to hatch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','egg','egg','yumurta','/eɡ/','Every day, she lays a golden egg.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','ducklings','ducklings','ördek yavruları','/ˈdʌklɪŋz/','When it opened, a large grey bird stepped out among her little ducklings.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','swim','swim','yüzmek','/swɪm/','He looked different from the others, but he could swim very well.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','well','well','kuyu','/wel/','A princess loved to play with her golden ball near a deep well.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','animals','animals','hayvanlar','/ˈænɪmlz/','He walks around and frightens the animals.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','brothers','brothers','erkek kardeşler','/ˈbrʌðəz/','Three brothers went into the forest to cut wood, one after another.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','nobody','nobody','hiç kimse','/ˈnoʊbədi/','Nobody is at home today.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','peace','peace','barış; huzur','/piːs/','Their father wants them to live in peace.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','hunters','hunters','avcılar','/ˈhʌntərz/','The hunters walk into the forest.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','frightened','frightened','korkmuş','/ˈfraɪtnd/','The frightened cat hides under the bed.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','hen','hen','tavuk','/hen/','A man owns a special hen.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','own','own','kendi','/oʊn/','She has her own room.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','eggs','eggs','yumurtalar','/eɡz/','The man sells the eggs and becomes rich.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','swans','swans','kuğular','/swɒnz/','Autumn came, and he saw a flock of beautiful white swans flying overhead.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','wings','wings','kanatlar','/wɪŋz/','Their long necks and powerful wings filled him with a feeling he did not understand.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','winter','winter','kış','/ˈwɪntə(r)/','Winter is cold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','ice','ice','buz','/aɪs/','One night, he became exhausted and was trapped in the ice.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','strong','strong','güçlü, sağlam','/strɔːŋ/','This bag is strong.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','reflection','reflection','yansıma','/rɪˈflekʃn/','When he looks down, he sees his reflection.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','swan','swan','kuğu','/swɒn/','He was no longer a grey, awkward youngster but a graceful white swan.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','suffering','suffering','acı','/ˈsʌfərɪŋ/','The Prince sees the people''s suffering.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','proud','proud','gururlu','/praʊd/','The crow feels proud.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c9ce94b2-5a45-597e-a124-a581d79e9b2e','unkind','unkind','kaba, kırıcı','/ʌnˈkaɪnd/','It was an unkind thing to say.');
