insert into public.content_assets(id,kind,storage_path,sha256,byte_size,mime_type) values('af68ad6b-a984-568e-abfc-e45573c3bc92','cover','covers/12b0edafc788ca9c7be21fa1504734f95af4122bfd3c9f8f6f7d5ced7943d4bb.png','12b0edafc788ca9c7be21fa1504734f95af4122bfd3c9f8f6f7d5ced7943d4bb',730146,'image/png') on conflict do nothing;
