insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('a81efb7a-4754-5d96-a4ff-867821e6242a','classic-emperors-clothes',1,'The Emperor’s New Clothes','Hans Christian Andersen','B1','Günlük yaşam','Kralın Yeni Giysileri. Kimsenin göremediğini söylemeye cesaret edemediği hayalî bir kumaş. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Edmund Dulac; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','af68ad6b-a984-568e-abfc-e45573c3bc92');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-01',1,'An emperor loved fine clothes more than anything else in his kingdom.','Bir imparator güzel kıyafetleri krallığındaki her şeyden çok severdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-02',2,'He spent so much time changing outfits that people joked about his wardrobe.','Kıyafet değiştirmeye o kadar çok zaman harcardı ki insanlar gardırobuyla ilgili şakalar yapardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-03',3,'One day, two swindlers arrived and claimed to be extraordinary weavers.','Bir gün iki dolandırıcı gelip olağanüstü dokumacılar olduklarını iddia etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-04',4,'They said their cloth had a remarkable power.','Kumaşlarının dikkat çekici bir gücü olduğunu söylediler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-05',5,'It was invisible to anyone who was foolish or unfit for a position.','Aptal ya da görevine uygun olmayan kişiler kumaşı göremiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-06',6,'The emperor thought such clothes would help him judge his officials.','İmparator böyle kıyafetlerin görevlilerini değerlendirmesine yardım edeceğini düşündü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-07',7,'He gave the men money, silk, and gold thread to begin their work.','İşe başlamaları için adamlara para, ipek ve altın iplik verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-08',8,'They kept the valuable materials and pretended to weave at empty looms.','Adamlar değerli malzemeleri kendilerine ayırıp boş tezgâhlarda dokuyormuş gibi yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-09',9,'The emperor sent a trusted minister to inspect the cloth.','İmparator kumaşı incelemesi için güvendiği bir bakanı gönderdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-10',10,'The minister saw nothing, but he was afraid to admit it.','Bakan hiçbir şey görmedi ama bunu itiraf etmekten korktu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-11',11,'He did not want anyone to think he was stupid or unfit for his job.','Kimsenin kendisini aptal ya da işine uygun olmayan biri sanmasını istemiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-12',12,'So he praised the wonderful colours and returned with an enthusiastic report.','Bu yüzden harika renkleri övüp coşkulu bir raporla geri döndü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-13',13,'A second official made the same choice for the same reason.','İkinci bir görevli de aynı nedenle aynı seçimi yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-14',14,'Soon the whole city was talking about the emperor''s amazing new clothes.','Çok geçmeden bütün şehir imparatorun şaşırtıcı yeni kıyafetlerini konuşuyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-15',15,'When the emperor visited the workshop, he could not see any cloth either.','İmparator atölyeyi ziyaret ettiğinde o da hiç kumaş göremedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-16',16,'He was horrified by what this might mean, but he joined the others in praising it.','Bunun ne anlama gelebileceği onu korkuttu ama o da diğerleriyle birlikte kumaşı övdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-17',17,'The swindlers worked through the night before a grand procession.','Dolandırıcılar büyük geçit töreninden önce gece boyunca çalışıyormuş gibi yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-18',18,'They moved their scissors through the air and stitched with needles that held no thread.','Makaslarını havada gezdirip üzerinde iplik olmayan iğnelerle dikiş diktiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-19',19,'In the morning, they helped the emperor put on his imaginary outfit.','Sabah imparatorun hayalî kıyafetlerini giymesine yardım ettiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-20',20,'His attendants pretended to lift the long train behind him.','Görevlileri arkasındaki uzun eteği kaldırıyormuş gibi yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-21',21,'The emperor walked through the streets while the crowd admired clothes that nobody could see.','İmparator sokaklarda yürürken kalabalık kimsenin göremediği kıyafetlere hayranlık gösteriyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-22',22,'Everyone feared being the first to say that something was wrong.','Herkes bir şeyin yanlış olduğunu söyleyen ilk kişi olmaktan korkuyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-23',23,'Then a child called out that the emperor had no clothes on.','Sonra bir çocuk, imparatorun üzerinde hiç giysi olmadığını haykırdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-24',24,'The child''s father repeated the remark, and the words passed through the crowd.','Çocuğun babası bu sözü tekrarladı ve söz kalabalıkta yayıldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-25',25,'Soon everyone was saying what they had known all along.','Çok geçmeden herkes başından beri bildiği şeyi söylüyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-26',26,'The emperor suspected that they were right.','İmparator onların haklı olduğundan şüphelendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-27',27,'Yet he decided that the procession must continue and held his head higher.','Yine de törenin sürmesi gerektiğine karar verip başını daha da dik tuttu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cl-emperors-clothes-28',28,'Behind him, the attendants still carried a train that did not exist.','Arkasında görevlileri, var olmayan bir eteği taşımaya devam ediyordu.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','emperor','emperor','imparator','/ˈempərə(r)/','An emperor loved fine clothes more than anything else in his kingdom.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','much','much','çok','/mʌtʃ/','Thank you very much.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','swindlers','swindlers','dolandırıcılar','/ˈswɪndləz/','One day, two swindlers arrived and claimed to be extraordinary weavers.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','weavers','weavers','dokumacılar','/ˈwiːvəz/','One day, two swindlers arrived and claimed to be extraordinary weavers.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','cloth','cloth','kumaş','/klɒθ/','He struck with a cloth and killed seven flies at once.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','invisible','invisible','görünmez','/ɪnˈvɪzəbl/','An old soldier met a woman who gave him useful advice and an invisible cloak.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','officials','officials','görevliler','/əˈfɪʃlz/','The emperor thought such clothes would help him judge his officials.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','money','money','para','/ˈmʌni/','She thinks about the money she can earn.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','silk','silk','ipek','/sɪlk/','They planned to make a ladder of silk so that she could escape.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','gold','gold','altın','/ɡəʊld/','He wants all the gold at once.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','valuable','valuable','değerli','/ˈvæljuəbəl/','The letter was valuable to her.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','weave','weave','dokumak','/wiːv/','They kept the valuable materials and pretended to weave at empty looms.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','looms','looms','dokuma tezgâhları','/luːmz/','They kept the valuable materials and pretended to weave at empty looms.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','nothing','nothing','hiçbir şey','/ˈnʌθɪŋ/','There is nothing in the box.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','second','second','ikinci','/ˈsekənd/','This is my second visit.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','procession','procession','geçit töreni','/prəˈseʃn/','The swindlers worked through the night before a grand procession.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','scissors','scissors','makas','/ˈsɪzəz/','He carefully uses the scissors.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','nobody','nobody','hiç kimse','/ˈnoʊbədi/','Nobody is at home today.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('a81efb7a-4754-5d96-a4ff-867821e6242a','father','father','baba','/ˈfɑːðə(r)/','A father has several sons.');
