insert into public.stories(id) values('classic-thumbelina') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','classic-thumbelina',1,'Thumbelina','Hans Christian Andersen','B1','Macera','Parmak Kız. Küçücük bir kızın kurbağalar, köstebekler ve bir kırlangıçla geçen yolculuğu. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Vilhelm Pedersen; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','609c57fd-a918-549b-a31f-a6e828f0ad3b');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-01',1,'A woman who longed for a child received a special barley seed from a fairy.','Çocuk özlemi çeken bir kadın, bir periden özel bir arpa tohumu aldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-02',2,'When she planted it, a flower opened to reveal a girl no taller than a thumb.','Tohumu ektiğinde açılan çiçeğin içinden parmak boyunu geçmeyen bir kız çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-03',3,'She named the girl Thumbelina and made her a bed in a walnut shell.','Kıza Parmak Kız adını verdi ve bir ceviz kabuğunda ona yatak hazırladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-04',4,'One night, a toad carried the sleeping girl away to marry her son.','Bir gece bir kurbağa, uyuyan kızı oğluyla evlendirmek için kaçırdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-05',5,'Thumbelina woke on a water-lily leaf, surrounded by water.','Parmak Kız, etrafı suyla çevrili bir nilüfer yaprağında uyandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-06',6,'Fish heard her crying and bit through the stem so that she could float away.','Balıklar ağladığını duyup sapı kemirerek kopardı; böylece kız suyun üzerinde uzaklaşabildi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-07',7,'A butterfly helped pull her leaf, but a beetle suddenly seized her.','Bir kelebek yaprağını çekmeye yardım etti ama bir böcek kızı aniden kapıp götürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-08',8,'At first, the beetle admired her, until the other beetles criticized her appearance.','Böcek önce kıza hayran oldu ama diğer böcekler görünüşünü eleştirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-09',9,'Then he abandoned her, and she lived alone among the plants through summer.','Sonra kızı bıraktı; kız yaz boyunca bitkilerin arasında tek başına yaşadı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-10',10,'When winter came, she became cold and desperately hungry.','Kış geldiğinde üşüdü ve korkunç derecede acıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-11',11,'A field mouse invited her into a warm home and offered her food.','Bir tarla faresi onu sıcak evine davet edip yiyecek sundu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-12',12,'In return, Thumbelina helped with the housework and told stories.','Parmak Kız da karşılığında ev işlerine yardım edip hikâyeler anlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-13',13,'The mouse''s wealthy neighbour, a mole, became interested in marrying her.','Farenin varlıklı komşusu olan bir köstebek onunla evlenmek istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-14',14,'He hated sunlight and preferred his dark underground passages.','Gün ışığından nefret ediyor ve karanlık yeraltı geçitlerini tercih ediyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-15',15,'While exploring one passage, Thumbelina found a swallow that seemed to be dead.','Parmak Kız bir geçidi keşfederken ölmüş gibi görünen bir kırlangıç buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-16',16,'She covered him gently and discovered that his heart was still beating.','Üzerini nazikçe örttü ve kalbinin hâlâ attığını fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-17',17,'Throughout winter, she secretly cared for him until he grew strong.','Kış boyunca güçlenene kadar ona gizlice baktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-18',18,'In spring, the swallow offered to carry her away, but she felt unable to leave the mouse.','Baharda kırlangıç onu götürmeyi teklif etti ama kız fareyi bırakamayacağını düşündü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-19',19,'Preparations began for her marriage to the mole, although she dreaded a life without the sun.','Parmak Kız güneşsiz bir hayattan korksa da köstebekle düğününün hazırlıkları başladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-20',20,'On the last day before the wedding, she went outside to say goodbye to the daylight.','Düğünden önceki son gün, gün ışığına veda etmek için dışarı çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-21',21,'The swallow returned and found her crying.','Kırlangıç döndü ve onu ağlarken buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-22',22,'This time, she accepted his offer and fastened herself safely to his back.','Bu kez teklifini kabul edip kendisini güvenle kuşun sırtına bağladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-23',23,'They flew over mountains and seas to a warm country filled with flowers.','Dağların ve denizlerin üzerinden uçarak çiçeklerle dolu sıcak bir ülkeye gittiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-24',24,'Inside a white flower, Thumbelina found a tiny prince with delicate wings.','Parmak Kız beyaz bir çiçeğin içinde narin kanatları olan minicik bir prens buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-25',25,'He was the king of the flower spirits, and he was exactly her size.','O, çiçek perilerinin kralıydı ve boyu tam kızın boyu kadardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-26',26,'Unlike the toad, beetle, and mole, he was someone she wished to marry.','Kurbağa, böcek ve köstebekten farklı olarak o, kızın evlenmek istediği biriydi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-27',27,'The flower spirits welcomed her and gave her a pair of wings and the new name Maia.','Çiçek perileri onu sevinçle karşılayıp bir çift kanat ve Maia adını verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','cl-thumbelina-28',28,'The swallow flew home with the story of the little girl he had helped.','Kırlangıç, yardım ettiği küçük kızın hikâyesiyle evine uçtu.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','barley','barley','arpa','/ˈbɑːli/','A woman who longed for a child received a special barley seed from a fairy.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','fairy','fairy','peri','/ˈfeəri/','A woman who longed for a child received a special barley seed from a fairy.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','thumb','thumb','başparmak','/θʌm/','A poor couple wished for a child, even one no bigger than a thumb.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','walnut','walnut','ceviz','/ˈwɔːlnʌt/','She named the girl Thumbelina and made her a bed in a walnut shell.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','toad','toad','kara kurbağası','/təʊd/','One night, a toad carried the sleeping girl away to marry her son.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','leaf','leaf','yaprak','/liːf/','He drops a leaf into the river.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','beetle','beetle','böcek','/ˈbiːtl/','A butterfly helped pull her leaf, but a beetle suddenly seized her.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','alone','alone','yalnız','/əˈloʊn/','He walks home alone.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','winter','winter','kış','/ˈwɪntə(r)/','Winter is cold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','hungry','hungry','aç','/ˈhʌŋɡri/','I am hungry after school.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','mouse','mouse','fare','/maʊs/','The mouse is very small.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','food','food','yiyecek','/fuːd/','He offers simple food from the fields.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','return','return','dönmek','/rɪˈtɜːrn/','They promised to return.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','mole','mole','köstebek','/məʊl/','The mouse''s wealthy neighbour, a mole, became interested in marrying her.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','swallow','swallow','kırlangıç','/ˈswɒləʊ/','The swallow flies across the city.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','strong','strong','güçlü, sağlam','/strɔːŋ/','This bag is strong.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','sun','sun','güneş','/sʌn/','The North Wind and the Sun argue.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','safely','safely','güvenli bir şekilde','/ˈseɪfli/','He put the ticket safely in his pocket.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','country','country','kır; ülke','/ˈkʌntri/','A country mouse invites his town friend to dinner.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','wings','wings','kanatlar','/wɪŋz/','Their long necks and powerful wings filled him with a feeling he did not understand.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('156d8f92-b9b4-5731-a5fe-217ed05b2ea4','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
