insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','classic-little-mermaid',1,'The Little Mermaid','Hans Christian Andersen','B1','Macera','Küçük Deniz Kızı. Bir deniz kızının insan dünyasına duyduğu özlem ve verdiği zor karar. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Edmund Dulac; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','81e70626-bcb6-50b3-a519-f893bfd5d093');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-01',1,'The youngest daughter of the sea king dreamed of the human world above the water.','Deniz kralının en küçük kızı, suyun üstündeki insan dünyasını hayal ediyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-02',2,'On her fifteenth birthday, she was finally allowed to visit the surface.','On beşinci doğum gününde sonunda yüzeye çıkmasına izin verildi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-03',3,'She saw a prince celebrating on a ship and was drawn to him.','Bir gemide kutlama yapan bir prens gördü ve ona ilgi duydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-04',4,'When a storm broke the ship apart, she carried him to shore.','Bir fırtına gemiyi parçalayınca prensi kıyıya taşıdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-05',5,'She hid nearby while a young woman found him, so he never saw his rescuer.','Genç bir kadın prensi bulurken deniz kızı yakında saklandı; bu yüzden prens kendisini kurtaranı hiç görmedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-06',6,'Back beneath the sea, she could think of little except the prince and his world.','Deniz altına döndüğünde aklına prens ve onun dünyası dışında pek bir şey gelmiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-07',7,'Her grandmother explained that mermaids lived for three hundred years but had no immortal soul.','Büyükannesi deniz kızlarının üç yüz yıl yaşadığını ama ölümsüz ruhları olmadığını açıkladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-08',8,'The little mermaid hoped to gain both human love and such a soul.','Küçük deniz kızı hem insan sevgisini hem de böyle bir ruhu kazanmayı umuyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-09',9,'She visited the sea witch, who offered a potion to change her tail into legs.','Kuyruğunu bacaklara dönüştüren bir iksir teklif eden deniz cadısını ziyaret etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-10',10,'The price was her beautiful voice, and every step on land would hurt.','Bunun bedeli güzel sesiydi ve karada attığı her adım canını yakacaktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-11',11,'She could never return as a mermaid, and if the prince married another, she would become foam.','Bir daha deniz kızı olarak dönemeyecekti; prens başka biriyle evlenirse köpüğe dönüşecekti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-12',12,'Despite these warnings, she drank the potion on the shore near the palace.','Bu uyarılara rağmen sarayın yakınındaki kıyıda iksiri içti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-13',13,'The prince found her and welcomed the silent stranger into his home.','Prens onu buldu ve sessiz yabancıyı evine kabul etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-14',14,'She walked and danced for him, hiding the pain that each movement caused.','Her hareketin verdiği acıyı gizleyerek prens için yürüyüp dans etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-15',15,'He grew fond of her but remembered the woman he believed had saved his life.','Prens onu sevdi ama hayatını kurtardığını sandığı kadını hatırlıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-16',16,'He said that only that woman could become his bride.','Yalnızca o kadının gelini olabileceğini söylüyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-17',17,'The mermaid could not tell him the truth because she had given away her voice.','Deniz kızı sesini verdiği için ona gerçeği anlatamıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-18',18,'When the prince visited a neighbouring kingdom, he recognized its princess as the woman from the shore.','Prens komşu bir krallığı ziyaret ettiğinde oranın prensesinin kıyıdaki kadın olduğunu fark etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-19',19,'Their wedding was celebrated aboard a ship.','Düğünleri bir gemide kutlandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-20',20,'The little mermaid knew that sunrise would bring the end of her life.','Küçük deniz kızı, gün doğumunun hayatının sonunu getireceğini biliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-21',21,'Her sisters rose from the sea with their hair cut short.','Kız kardeşleri saçları kısacık kesilmiş hâlde denizden çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-22',22,'They had traded their hair to the witch for a knife.','Bir bıçak almak için saçlarını cadıya vermişlerdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-23',23,'If the mermaid killed the prince before dawn, she could return to the sea.','Deniz kızı şafaktan önce prensi öldürürse denize dönebilecekti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-24',24,'She entered his room and saw him asleep beside his bride.','Prensin odasına girip onu gelininin yanında uyurken gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-25',25,'But she could not kill the person she loved, even to save herself.','Ama kendisini kurtarmak için bile sevdiği kişiyi öldüremedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-26',26,'She threw the knife into the sea and followed it into the waves.','Bıçağı denize attı ve ardından kendisi de dalgalara atladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-27',27,'Instead of disappearing completely, she rose among the daughters of the air.','Tamamen yok olmak yerine hava kızlarının arasına yükseldi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-28',28,'They explained that good deeds could help her earn an immortal soul.','İyi davranışlarının ölümsüz bir ruh kazanmasına yardım edebileceğini açıkladılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','cl-little-mermaid-29',29,'Invisible to the prince, she began a new life of service and hope.','Prense görünmeden, iyilik ve umutla dolu yeni bir hayata başladı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','surface','surface','yüzey','/ˈsɜːfɪs/','On her fifteenth birthday, she was finally allowed to visit the surface.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','soul','soul','ruh','/səʊl/','Her grandmother explained that mermaids lived for three hundred years but had no immortal soul.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','mermaid','mermaid','deniz kızı','/ˈmɜːmeɪd/','The little mermaid hoped to gain both human love and such a soul.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','witch','witch','cadı','/wɪtʃ/','The old woman is a witch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','potion','potion','iksir','/ˈpəʊʃn/','She visited the sea witch, who offered a potion to change her tail into legs.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','tail','tail','kuyruk','/teɪl/','She visited the sea witch, who offered a potion to change her tail into legs.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','voice','voice','ses','/vɔɪs/','"You must have a beautiful voice, too."');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','step','step','adım','/step/','Take one step at a time.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','return','return','dönmek','/rɪˈtɜːrn/','They promised to return.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','married','married','evlendi','/ˈmærid/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','foam','foam','köpük','/fəʊm/','She could never return as a mermaid, and if the prince married another, she would become foam.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','bride','bride','gelin','/braɪd/','The prince hopes to find a bride.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','truth','truth','gerçek','/truːθ/','A liar can lose people''s trust, even when he tells the truth.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','princess','princess','prenses','/ˌprɪnˈses/','She arrived in anger and placed a curse on the princess.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','knife','knife','bıçak','/naɪf/','They had traded their hair to the witch for a knife.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','asleep','asleep','uykuda','/əˈsliːp/','The hare is asleep.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','earn','earn','kazanmak','/ɜːn/','She thinks about the money she can earn.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('4f3a3e1a-e254-5c1a-a2a8-d3b8a18c9797','invisible','invisible','görünmez','/ɪnˈvɪzəbl/','An old soldier met a woman who gave him useful advice and an invisible cloak.');
