insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('c8a1e704-196c-5104-a926-997c46877519','classic-snow-queen',1,'The Snow Queen','Hans Christian Andersen','B1','Macera','Karlar Kraliçesi. Gerda, kalbi buz kesen arkadaşı Kay’i bulmak için uzun bir yolculuğa çıkar. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Edmund Dulac; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','e78e751b-fd81-50df-aa0a-88e54c649ce5');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-01',1,'A wicked spirit made a mirror that turned beautiful things ugly and kindness into faults.','Kötü bir ruh, güzel şeyleri çirkin, iyilikleri kusur gibi gösteren bir ayna yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-02',2,'When the mirror broke, tiny pieces scattered across the world.','Ayna kırıldığında minicik parçalar dünyanın her yanına dağıldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-03',3,'A piece in an eye changed what a person saw, and one in a heart made it cold.','Göze giren bir parça kişinin gördüklerini değiştiriyor, kalbe giren bir parça da onu soğutuyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-04',4,'Two children, Kay and Gerda, lived close together and loved the roses between their homes.','Kay ile Gerda adındaki iki çocuk birbirine yakın yaşıyor ve evlerinin arasındaki gülleri seviyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-05',5,'One day, pieces of the mirror entered Kay''s eye and heart.','Bir gün aynanın parçaları Kay''in gözüne ve kalbine girdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-06',6,'He became cruel and began to mock the things he had once loved.','Acımasızlaştı ve bir zamanlar sevdiği şeylerle alay etmeye başladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-07',7,'During winter, he tied his little sledge to a larger one in the town square.','Kışın kasaba meydanında küçük kızağını daha büyük bir kızağa bağladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-08',8,'Its driver was the Snow Queen, who carried him far away.','Kızağı süren Karlar Kraliçesi''ydi ve onu çok uzaklara götürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-09',9,'Her cold kisses made him forget Gerda and his home.','Kraliçenin soğuk öpücükleri ona Gerda''yı ve evini unutturdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-10',10,'Gerda refused to believe he was lost forever and set out to find him.','Gerda onun sonsuza kadar kaybolduğuna inanmayı reddedip onu aramaya çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-11',11,'She offered the river her red shoes and was carried downstream in a little boat.','Nehre kırmızı ayakkabılarını sundu ve küçük bir kayıkta akıntıyla sürüklendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-12',12,'An old woman welcomed her into an enchanted garden and tried to make her forget her search.','Yaşlı bir kadın onu büyülü bir bahçeye kabul etti ve arayışını unutturmaya çalıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-13',13,'But a reminder of roses brought Kay back to her thoughts, and she escaped.','Ama gülleri hatırlatan bir şey Kay''i yeniden aklına getirdi ve kız kaçtı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-14',14,'A crow told her about a clever princess who had recently married.','Bir karga ona yakın zamanda evlenmiş akıllı bir prensesi anlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-15',15,'Hoping that the bridegroom was Kay, Gerda entered the palace.','Damadın Kay olduğunu uman Gerda saraya girdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-16',16,'He was not her friend, but the prince and princess gave her warm clothes and a carriage.','Damat arkadaşı değildi ama prens ile prenses ona sıcak giysiler ve bir araba verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-17',17,'Robbers attacked the carriage and carried Gerda to their camp.','Haydutlar arabaya saldırıp Gerda''yı kamplarına götürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-18',18,'A fierce robber girl kept her close, while pigeons told them that Kay had gone north.','Yabani bir haydut kızı onu yanında tutarken güvercinler Kay''in kuzeye gittiğini anlattı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-19',19,'Moved by Gerda''s story, the girl freed her and lent her a reindeer.','Gerda''nın hikâyesinden etkilenen kız onu serbest bırakıp bir ren geyiğini ödünç verdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-20',20,'The reindeer carried her through the cold to a woman in Lapland.','Ren geyiği onu soğuğun içinden Laponya''daki bir kadına taşıdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-21',21,'That woman sent them onward to a wise Finnish woman.','O kadın da onları bilge bir Fin kadına gönderdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-22',22,'The reindeer asked for a power that would help Gerda defeat the Snow Queen.','Ren geyiği, Gerda''nın Karlar Kraliçesi''ni yenmesine yardım edecek bir güç istedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-23',23,'The wise woman said that the girl''s loving heart was already her greatest strength.','Bilge kadın, kızın sevgi dolu kalbinin zaten en büyük gücü olduğunu söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-24',24,'Gerda went on alone, praying as the snow around her became threatening shapes.','Çevresindeki kar tehditkâr şekillere dönüşürken Gerda dua ederek tek başına ilerledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-25',25,'At last, she entered the vast, empty halls of the Snow Queen''s palace.','Sonunda Karlar Kraliçesi''nin sarayındaki uçsuz bucaksız, boş salonlara girdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-26',26,'Kay sat arranging pieces of ice, trying to form the word eternity.','Kay oturmuş, buz parçalarını dizerek sonsuzluk kelimesini oluşturmaya çalışıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-27',27,'He did not recognize Gerda until her warm tears reached his frozen heart.','Gerda''nın sıcak gözyaşları donmuş kalbine ulaşana kadar onu tanımadı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-28',28,'As she sang a familiar song, he began to cry and the piece in his eye washed out.','Kız tanıdık bir şarkı söylerken Kay ağlamaya başladı ve gözündeki parça gözyaşlarıyla çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-29',29,'They embraced, and the ice pieces formed the word that freed him.','Birbirlerine sarıldılar ve buz parçaları Kay''i özgürleştiren kelimeyi oluşturdu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-30',30,'Together, they travelled home and thanked those who had helped them.','Birlikte eve döndüler ve kendilerine yardım edenlere teşekkür ettiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-31',31,'They found that they had grown older, though their hearts were still like children''s.','Büyümüş olduklarını gördüler ama kalpleri hâlâ çocuk kalbi gibiydi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('c8a1e704-196c-5104-a926-997c46877519','cl-snow-queen-32',32,'It was summer again, and the roses were in bloom.','Yeniden yaz gelmişti ve güller açmıştı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','mirror','mirror','ayna','/ˈmɪrə(r)/','The new queen asked her magic mirror who was the most beautiful.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','pieces','pieces','parçalar','/ˈpiːsɪz/','She cuts the bread into small pieces.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','winter','winter','kış','/ˈwɪntə(r)/','Winter is cold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','sledge','sledge','kızak','/sledʒ/','During winter, he tied his little sledge to a larger one in the town square.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','queen','queen','kraliçe','/kwiːn/','A queen had a daughter with skin as white as snow and hair as black as ebony.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','believe','believe','inanmak','/bɪˈliːv/','I believe you.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','river','river','nehir','/ˈrɪvər/','The river moved slowly.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','boat','boat','tekne','/boʊt/','A little boat floated away.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','crow','crow','karga','/krəʊ/','A thirsty crow looks for water.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','clever','clever','akıllı','/ˈklevə(r)/','A clever idea can solve a difficult problem.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','princess','princess','prenses','/ˌprɪnˈses/','She arrived in anger and placed a curse on the princess.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','married','married','evlendi','/ˈmærid/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','prince','prince','prens','/prɪns/','A prince saw her and asked to take the coffin with him.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','robbers','robbers','haydutlar','/ˈrɒbəz/','The robbers leave the house.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','north','north','kuzey','/nɔːθ/','The North Wind and the Sun argue.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','reindeer','reindeer','ren geyiği','/ˈreɪndɪə(r)/','Moved by Gerda''s story, the girl freed her and lent her a reindeer.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','help','help','yardım','/help/','Thank you for your help.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','alone','alone','yalnız','/əˈloʊn/','He walks home alone.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','praying','praying','dua etme','/ˈpreɪɪŋ/','Gerda went on alone, praying as the snow around her became threatening shapes.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','ice','ice','buz','/aɪs/','One night, he became exhausted and was trapped in the ice.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','eternity','eternity','sonsuzluk','/ɪˈtɜːnəti/','Kay sat arranging pieces of ice, trying to form the word eternity.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('c8a1e704-196c-5104-a926-997c46877519','tears','tears','gözyaşları','/tɪəz/','Her tears fell into his eyes, and he could see once more.');
