insert into public.stories(id) values('classic-little-match-girl') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','classic-little-match-girl',1,'The Little Match Girl','Hans Christian Andersen','B1','Günlük yaşam','Kibritçi Kız. Soğuk bir yılbaşı gecesinde, küçük bir kızın sıcaklık ve sevgi özlemi. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Vilhelm Pedersen; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','0a726862-032e-5060-ac4d-9e23851a5810');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-01',1,'On the last evening of the year, snow fell through the dark streets.','Yılın son akşamında kar, karanlık sokaklara yağıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-02',2,'A little girl walked alone, trying to sell matches.','Küçük bir kız tek başına yürüyerek kibrit satmaya çalışıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-03',3,'She had left home wearing slippers much too large for her.','Evden kendisine çok büyük gelen terliklerle çıkmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-04',4,'But she lost them while running away from two passing carriages.','Ama geçen iki arabadan kaçarken terliklerini kaybetmişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-05',5,'Now her bare feet were red and blue with cold.','Şimdi çıplak ayakları soğuktan kızarıp morarmıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-06',6,'Nobody had bought her matches or given her a coin all day.','Bütün gün kimse kibritlerini almamış ya da ona bir bozuk para vermemişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-07',7,'She was afraid to go home without money because her father would beat her.','Parasız eve gitmekten korkuyordu çünkü babası onu dövecekti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-08',8,'And the poor home was scarcely warmer than the street.','Üstelik yoksul evleri sokaktan ancak biraz daha sıcaktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-09',9,'She sat in a corner between two houses and drew her feet beneath her.','İki evin arasındaki bir köşeye oturup ayaklarını altına çekti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-10',10,'The smell of roast goose came from the nearby houses.','Yakındaki evlerden kızarmış kaz kokusu geliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-11',11,'To warm her fingers, she struck a match against the wall.','Parmaklarını ısıtmak için duvara sürterek bir kibrit yaktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-12',12,'In its light, she imagined a great iron stove giving out wonderful heat.','Işığında, harika bir sıcaklık yayan büyük bir demir soba hayal etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-13',13,'She stretched out her feet, but the match went out and the stove disappeared.','Ayaklarını uzattı ama kibrit söndü ve soba kayboldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-14',14,'She lit another match and saw a table with a delicious supper.','Başka bir kibrit yaktı ve üzerinde nefis bir akşam yemeği olan bir masa gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-15',15,'The roast goose seemed to move toward her before the light faded.','Işık solmadan önce kızarmış kaz ona doğru ilerler gibi oldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-16',16,'A third match revealed a shining Christmas tree with countless candles.','Üçüncü bir kibrit, sayısız mumla parlayan bir Noel ağacını ortaya çıkardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-17',17,'As the flame died, its lights rose and became stars.','Alev sönerken ışıklar yükselip yıldızlara dönüştü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-18',18,'One star fell, and the girl remembered something her grandmother had once said.','Bir yıldız kaydı ve kız büyükannesinin bir zamanlar söylediği bir şeyi hatırladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-19',19,'A falling star meant that a soul was going to God.','Kayan bir yıldız, bir ruhun Tanrı''ya gittiği anlamına geliyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-20',20,'Her grandmother had been the only person who had treated her with kindness.','Büyükannesi ona iyilikle davranan tek kişi olmuştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-21',21,'When she struck the next match, the old woman appeared in the light.','Sonraki kibriti yaktığında yaşlı kadın ışığın içinde belirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-22',22,'The girl begged her not to disappear like the stove, supper, and tree.','Kız ona soba, yemek ve ağaç gibi kaybolmaması için yalvardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-23',23,'She lit the remaining matches together to keep her grandmother near.','Büyükannesini yanında tutmak için kalan kibritleri bir arada yaktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-24',24,'In their brightness, her grandmother lifted her into her arms.','Kibritlerin parlaklığında büyükannesi onu kollarına aldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-25',25,'Together they rose beyond cold, hunger, and fear.','Birlikte soğuğun, açlığın ve korkunun ötesine yükseldiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-26',26,'In the morning, people found the girl dead in the corner, with a smile on her face.','Sabah insanlar kızı köşede ölmüş olarak buldu; yüzünde bir gülümseme vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-27',27,'They saw the burnt matches and said she had tried to warm herself.','Yanmış kibritleri görüp ısınmaya çalışmış olduğunu söylediler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','cl-little-match-girl-28',28,'They could not see the visions that had comforted her during her final night.','Son gecesinde onu teselli eden hayalleri göremiyorlardı.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','alone','alone','yalnız','/əˈloʊn/','He walks home alone.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','matches','matches','kibritler','/ˈmætʃɪz/','A little girl walked alone, trying to sell matches.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','much','much','çok','/mʌtʃ/','Thank you very much.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','bare','bare','çıplak','/beə(r)/','Now her bare feet were red and blue with cold.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','nobody','nobody','hiç kimse','/ˈnoʊbədi/','Nobody is at home today.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','coin','coin','bozuk para','/kɔɪn/','Nobody had bought her matches or given her a coin all day.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','money','money','para','/ˈmʌni/','She thinks about the money she can earn.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','father','father','baba','/ˈfɑːðə(r)/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','goose','goose','kaz','/ɡuːs/','Under its roots, he found a goose with golden feathers.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','iron','iron','demir','/ˈaɪən/','A carriage arrived with the prince''s loyal servant, Iron Henry.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','stove','stove','soba','/stəʊv/','He suggested telling it to an iron stove instead, and listened from outside.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','supper','supper','akşam yemeği','/ˈsʌpə(r)/','The animals eat their supper.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','flame','flame','alev','/fleɪm/','The flame lights his face.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','soul','soul','ruh','/səʊl/','Her grandmother explained that mermaids lived for three hundred years but had no immortal soul.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','hunger','hunger','açlık','/ˈhʌŋɡə(r)/','Together they rose beyond cold, hunger, and fear.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','morning','morning','sabah','/ˈmɔːrnɪŋ/','It was a bright morning.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','smile','smile','gülümsemek','/smaɪl/','She gave him a warm smile.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('6181a7f0-afba-5f73-ae82-6e72f9c5780a','visions','visions','hayaller','/ˈvɪʒnz/','They could not see the visions that had comforted her during her final night.');
