insert into public.content_assets(id,kind,storage_path,sha256,byte_size,mime_type) values('35bf611f-da57-5f84-ad2a-2b507e32421f','cover','covers/c991e9dfa8ed5be003786d8d1da2f50fd815cca4b6e98edf8e5d558bb22be593.png','c991e9dfa8ed5be003786d8d1da2f50fd815cca4b6e98edf8e5d558bb22be593',557651,'image/png') on conflict do nothing;
insert into public.stories(id) values('classic-steadfast-tin-soldier') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','classic-steadfast-tin-soldier',1,'The Steadfast Tin Soldier','Hans Christian Andersen','B1','Macera','Kurşun Asker. Tek bacaklı bir oyuncak askerin kâğıt kayıktan bir balığın içine uzanan serüveni. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Vilhelm Pedersen; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','35bf611f-da57-5f84-ad2a-2b507e32421f');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-01',1,'A boy received a box of twenty-five tin soldiers for his birthday.','Bir çocuk doğum gününde yirmi beş kalay askerden oluşan bir kutu aldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-02',2,'The last soldier had only one leg because there had not been enough tin.','Son askerin yalnızca bir bacağı vardı çünkü yeterince kalay kalmamıştı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-03',3,'Still, he stood as firmly as the others on his single leg.','Yine de tek bacağı üzerinde diğerleri kadar sağlam duruyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-04',4,'Nearby, a paper dancer stood at the entrance of a toy castle.','Yakında, oyuncak bir şatonun girişinde kâğıttan bir dansçı duruyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-05',5,'She held one leg so high that the soldier believed she had only one, too.','Bir bacağını o kadar yukarı kaldırmıştı ki asker onun da tek bacağı olduğunu sandı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-06',6,'He admired her from behind a small box and dreamed of being her companion.','Küçük bir kutunun arkasından ona hayranlıkla bakıyor ve arkadaşı olmayı hayal ediyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-07',7,'At night, the toys came alive, but the soldier and dancer remained perfectly still.','Geceleri oyuncaklar canlanıyordu ama asker ile dansçı tamamen hareketsiz kalıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-08',8,'A goblin in a box warned the soldier not to look at the dancer.','Bir kutunun içindeki cin, askere dansçıya bakmamasını söyledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-09',9,'The next day, someone placed the soldier on a windowsill.','Ertesi gün biri askeri pencere pervazına koydu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-10',10,'The window flew open, and he fell into the street below.','Pencere aniden açıldı ve asker aşağıdaki sokağa düştü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-11',11,'The boy and his servant searched, but the silent soldier did not call out.','Çocuk ile hizmetçisi aradı ama sessiz asker seslenmedi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-12',12,'After rain, two other boys found him and made a boat from newspaper.','Yağmurdan sonra başka iki çocuk onu buldu ve gazeteden bir kayık yaptı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-13',13,'They put him inside and sent him down the gutter.','Onu içine koyup oluğun suyuna bıraktılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-14',14,'The boat rushed into a dark passage beneath the street.','Kayık hızla sokağın altındaki karanlık bir geçide girdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-15',15,'A rat demanded his passport and chased after him.','Bir sıçan pasaportunu isteyip peşinden koştu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-16',16,'The current carried the boat onward until it plunged into deeper water.','Akıntı kayığı taşıdı ve kayık daha derin suya daldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-17',17,'The paper tore, the boat sank, and a large fish swallowed the soldier.','Kâğıt yırtıldı, kayık battı ve büyük bir balık askeri yuttu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-18',18,'Inside the fish, he still held his gun and thought about the dancer.','Balığın içinde hâlâ tüfeğini tutuyor ve dansçıyı düşünüyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-19',19,'Later, the fish was caught, sold, and carried into a kitchen.','Daha sonra balık yakalandı, satıldı ve bir mutfağa götürüldü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-20',20,'A cook cut it open and discovered the little soldier.','Bir aşçı balığı kesip açtı ve küçük askeri buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-21',21,'By a remarkable chance, he was back in the same house where his journey had begun.','Şaşırtıcı bir rastlantıyla yolculuğunun başladığı eve dönmüştü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-22',22,'He saw the dancer still standing in the doorway of the toy castle.','Dansçının hâlâ oyuncak şatonun kapısında durduğunu gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-23',23,'Neither said a word, but he continued to gaze at her.','İkisi de tek kelime söylemedi ama asker ona bakmayı sürdürdü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-24',24,'Suddenly, a little boy threw the soldier into the stove without explaining why.','Küçük bir çocuk nedenini açıklamadan askeri birden sobaya attı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-25',25,'As he began to melt, a gust of air carried the paper dancer into the fire beside him.','Asker erimeye başlarken bir hava akımı kâğıt dansçıyı da onun yanındaki ateşe sürükledi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-26',26,'She burned at once, while the soldier melted into a small heart-shaped lump.','Dansçı hemen yanıp kül oldu; asker ise eriyerek kalp şeklinde küçük bir parçaya dönüştü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-27',27,'The next day, the servant found the tin heart among the ashes.','Ertesi gün hizmetçi küllerin arasında kalay kalbi buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('bcd37c77-4d88-56a4-a84c-887326b3b99e','cl-steadfast-tin-soldier-28',28,'Only the dancer''s burnt ornament remained beside it.','Yanında dansçının yalnızca yanmış süsü kalmıştı.');
