insert into public.content_assets(id,kind,storage_path,sha256,byte_size,mime_type) values('b6779dde-8649-57c2-a174-e78c4221ada7','cover','covers/d9dc75ff532ecae511b8b3ef7ec5ad1fca7fc03acee440fc48646fe6805f0497.png','d9dc75ff532ecae511b8b3ef7ec5ad1fca7fc03acee440fc48646fe6805f0497',341455,'image/png') on conflict do nothing;
insert into public.stories(id) values('classic-wild-swans') on conflict do nothing;
insert into public.story_revisions(id,story_id,revision,title,author,level,genre,description,cover_asset_id) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','classic-wild-swans',1,'The Wild Swans','Hans Christian Andersen','B1','Macera','Yaban Kuğuları. Elisa, büyülenmiş on bir kardeşini kurtarmak için sessizlik içinde çalışır. B1 düzeyinde kısa uyarlama. Uyarlama ve Türkçe çeviri: English Tales. Tarihî görsel: Vilhelm Pedersen; kitap içi illüstrasyon, ayrı bir ilk baskı kapağı değildir.','b6779dde-8649-57c2-a174-e78c4221ada7');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-01',1,'A king had eleven sons and a daughter named Elisa.','Bir kralın on bir oğlu ve Elisa adında bir kızı vardı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-02',2,'After he married a cruel queen, the children''s happy life changed.','Zalim bir kraliçeyle evlenince çocukların mutlu hayatı değişti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-03',3,'The queen sent Elisa away and turned her brothers into wild swans.','Kraliçe Elisa''yı uzaklara gönderdi ve erkek kardeşlerini yaban kuğularına çevirdi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-04',4,'When Elisa returned as a young woman, the queen made her look so strange that her father rejected her.','Elisa genç bir kadın olarak döndüğünde kraliçe onu öyle garip bir görünüme soktu ki babası onu reddetti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-05',5,'Alone in the forest, Elisa washed away the disguise and went looking for her brothers.','Ormanda yalnız kalan Elisa görünüşünü değiştiren kirleri yıkayıp kardeşlerini aramaya çıktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-06',6,'She reached the sea and found eleven swan feathers on the shore.','Denize ulaşıp kıyıda on bir kuğu tüyü buldu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-07',7,'At sunset, the swans landed and became her brothers again.','Gün batımında kuğular yere konup yeniden kardeşlerine dönüştü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-08',8,'They explained that they were birds by day and men only after the sun went down.','Gündüz kuş, ancak güneş battıktan sonra insan olduklarını açıkladılar.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-09',9,'The brothers carried Elisa across the sea in a net, racing against the sunset.','Kardeşleri gün batımına karşı yarışarak Elisa''yı bir ağın içinde denizin ötesine taşıdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-10',10,'In their distant home, she dreamed of a fairy who told her how to break the spell.','Uzaklardaki evlerinde, büyüyü nasıl bozacağını söyleyen bir periyi rüyasında gördü.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-11',11,'She must gather nettles and weave eleven shirts from their fibres.','Isırgan otları toplayıp liflerinden on bir gömlek dokumalıydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-12',12,'The nettles would burn her hands, and she must not speak until the work was finished.','Isırganlar ellerini yakacaktı ve iş bitene kadar konuşmamalıydı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-13',13,'A single word would bring death to her brothers.','Tek bir kelime kardeşlerinin ölümüne neden olacaktı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-14',14,'Elisa accepted the painful task and began to work in silence.','Elisa acı veren görevi kabul edip sessizlik içinde çalışmaya başladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-15',15,'A young king found her in the forest and was moved by her beauty and sadness.','Genç bir kral onu ormanda buldu ve güzelliği ile hüznünden etkilendi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-16',16,'He brought her to his palace, where they later married.','Onu sarayına götürdü ve daha sonra evlendiler.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-17',17,'Although he loved her, his adviser suspected that her silence hid something wicked.','Kral onu sevse de danışmanı, sessizliğinin kötü bir şeyi gizlediğinden şüpheleniyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-18',18,'At night, Elisa visited a churchyard to gather more nettles.','Elisa geceleri daha fazla ısırgan toplamak için bir mezarlığa gidiyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-19',19,'The adviser saw her there and convinced the king that she was a witch.','Danışman onu orada görüp kralı onun bir cadı olduğuna inandırdı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-20',20,'She could not defend herself without endangering her brothers.','Kardeşlerini tehlikeye atmadan kendisini savunamıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-21',21,'Even after she was sentenced to burn, she continued weaving in prison.','Yakılmaya mahkûm edildikten sonra bile hapiste dokumaya devam etti.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-22',22,'On the way to the fire, she worked on the last unfinished sleeve.','Ateşe götürülürken bitmemiş son kol üzerinde çalışıyordu.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-23',23,'The eleven swans arrived and flew around her.','On bir kuğu gelip çevresinde uçmaya başladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-24',24,'She threw the shirts over them just before the sentence could be carried out.','Ceza uygulanamadan hemen önce gömlekleri üzerlerine attı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-25',25,'They became princes again, although the youngest kept one wing because his sleeve was unfinished.','Yeniden prenslere dönüştüler ama gömleğinin kolu bitmediği için en küçüğünün bir kanadı kaldı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-26',26,'Now Elisa could speak and explain that she was innocent.','Elisa artık konuşup suçsuz olduğunu açıklayabildi.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-27',27,'Her brothers told the whole story, and the king understood her long silence.','Kardeşleri bütün hikâyeyi anlattı ve kral onun uzun sessizliğini anladı.');
insert into public.story_sentences(revision_id,id,position,english,turkish) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','cl-wild-swans-28',28,'The wood around her blossomed into roses, turning the place of death into a place of joy.','Çevresindeki odunlar güllere dönüştü; ölüm yeri bir sevinç yerine dönüştü.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','king','king','kral','/kɪŋ/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','sons','sons','oğullar','/sʌnz/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','married','married','evlendi','/ˈmærid/','After the queen died, the king married another woman.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','queen','queen','kraliçe','/kwiːn/','A queen had a daughter with skin as white as snow and hair as black as ebony.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','brothers','brothers','erkek kardeşler','/ˈbrʌðəz/','Three brothers went into the forest to cut wood, one after another.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','swans','swans','kuğular','/swɒnz/','Autumn came, and he saw a flock of beautiful white swans flying overhead.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','father','father','baba','/ˈfɑːðə(r)/','A father has several sons.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','alone','alone','yalnız','/əˈloʊn/','He walks home alone.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','forest','forest','orman','/ˈfɔːrɪst/','The forest was full of birds.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','disguise','disguise','kılık','/dɪsˈɡaɪz/','A fine disguise cannot hide who we are forever.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','swan','swan','kuğu','/swɒn/','He was no longer a grey, awkward youngster but a graceful white swan.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','feathers','feathers','tüyler','/ˈfeðəz/','"What beautiful feathers you have!" he says.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','sun','sun','güneş','/sʌn/','The North Wind and the Sun argue.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','fairy','fairy','peri','/ˈfeəri/','A woman who longed for a child received a special barley seed from a fairy.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','break','break','kırmak','/breɪk/','"Try to break this bundle," he says.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','spell','spell','büyü','/spel/','As his master rode home free of the spell, the bands broke with joy.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','nettles','nettles','ısırgan otları','/ˈnetlz/','She must gather nettles and weave eleven shirts from their fibres.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','weave','weave','dokumak','/wiːv/','They kept the valuable materials and pretended to weave at empty looms.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','shirts','shirts','gömlekler','/ʃɜːts/','The wife made tiny shirts, coats, and trousers.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','fibres','fibres','lifler','/ˈfaɪbəz/','She must gather nettles and weave eleven shirts from their fibres.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','single','single','tek','/ˈsɪŋɡl/','He gives each son a single stick.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','silence','silence','sessizlik','/ˈsaɪləns/','Elisa accepted the painful task and began to work in silence.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','adviser','adviser','danışman','/ədˈvaɪzə(r)/','Although he loved her, his adviser suspected that her silence hid something wicked.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','witch','witch','cadı','/wɪtʃ/','The old woman is a witch.');
insert into public.revision_words(revision_id,id,word,translation,pronunciation,example) values('60e24bb4-83c3-5a1b-a45d-22826bcd3316','innocent','innocent','suçsuz','/ˈɪnəsnt/','Now Elisa could speak and explain that she was innocent.');
